const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');
const bcrypt = require('bcryptjs');

const dbPath = path.join(__dirname, '..', '..', 'training_agency.db');
const backupsDir = path.join(__dirname, '..', '..', 'backups');

if (!fs.existsSync(backupsDir)) {
  fs.mkdirSync(backupsDir, { recursive: true });
}

let db = new Database(dbPath);
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

function getDb() {
  return db;
}

function initDb() {
  const schema = `
    -- Admins Table
    CREATE TABLE IF NOT EXISTS admins (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      name TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    -- Training Levels Table
    CREATE TABLE IF NOT EXISTS training_levels (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT UNIQUE NOT NULL,
      order_index INTEGER NOT NULL DEFAULT 1,
      status TEXT CHECK(status IN ('active', 'inactive')) DEFAULT 'active',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    -- Subjects Table
    CREATE TABLE IF NOT EXISTS subjects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      level_id INTEGER NOT NULL,
      name TEXT NOT NULL,
      is_required INTEGER NOT NULL DEFAULT 1, -- 1: Required, 0: Optional
      status TEXT CHECK(status IN ('active', 'inactive')) DEFAULT 'active',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (level_id) REFERENCES training_levels (id) ON DELETE CASCADE
    );

    -- Training Master Table
    CREATE TABLE IF NOT EXISTS trainings (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      code TEXT,
      name TEXT NOT NULL,
      subject_id INTEGER NOT NULL,
      has_quiz INTEGER NOT NULL DEFAULT 1, -- 1: Yes, 0: No
      passing_grade INTEGER DEFAULT 75,
      status TEXT CHECK(status IN ('active', 'inactive')) DEFAULT 'active',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (subject_id) REFERENCES subjects (id) ON DELETE RESTRICT
    );

    -- Training Sessions / Batches Table
    CREATE TABLE IF NOT EXISTS training_sessions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      training_id INTEGER NOT NULL,
      batch_name TEXT NOT NULL,
      date TEXT NOT NULL,
      trainer TEXT,
      location TEXT,
      status TEXT CHECK(status IN ('Scheduled', 'Ongoing', 'Completed', 'Cancelled')) DEFAULT 'Scheduled',
      notes TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (training_id) REFERENCES trainings (id) ON DELETE RESTRICT
    );

    -- Participants / Agents Table
    CREATE TABLE IF NOT EXISTS participants (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      email TEXT UNIQUE NOT NULL,
      nik TEXT,
      phone TEXT,
      branch TEXT,
      status TEXT CHECK(status IN ('active', 'inactive')) DEFAULT 'active',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    -- Session Participants & Attendance Table
    CREATE TABLE IF NOT EXISTS session_participants (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      session_id INTEGER NOT NULL,
      participant_id INTEGER NOT NULL,
      attendance TEXT CHECK(attendance IN ('Hadir', 'Tidak Hadir', 'Belum')) DEFAULT 'Belum',
      status TEXT CHECK(status IN ('Registered', 'Completed')) DEFAULT 'Registered',
      completed_at DATETIME,
      notes TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      UNIQUE(session_id, participant_id),
      FOREIGN KEY (session_id) REFERENCES training_sessions (id) ON DELETE CASCADE,
      FOREIGN KEY (participant_id) REFERENCES participants (id) ON DELETE CASCADE
    );

    -- Quiz Scores Table
    CREATE TABLE IF NOT EXISTS quiz_scores (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      session_id INTEGER NOT NULL,
      participant_id INTEGER NOT NULL,
      score REAL NOT NULL CHECK(score >= 0 AND score <= 100),
      result TEXT CHECK(result IN ('PASS', 'FAIL')) NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      UNIQUE(session_id, participant_id),
      FOREIGN KEY (session_id) REFERENCES training_sessions (id) ON DELETE CASCADE,
      FOREIGN KEY (participant_id) REFERENCES participants (id) ON DELETE CASCADE
    );
  `;

  db.exec(schema);

  // Seed default admin if none exists
  const adminCount = db.prepare('SELECT COUNT(*) as count FROM admins').get();
  if (adminCount.count === 0) {
    const salt = bcrypt.genSaltSync(10);
    const hash = bcrypt.hashSync('admin123', salt);
    db.prepare(`
      INSERT INTO admins (username, password_hash, name) 
      VALUES (?, ?, ?)
    `).run('admin', hash, 'Administrator Training');
  }

  // Seed default levels if none exists
  const levelCount = db.prepare('SELECT COUNT(*) as count FROM training_levels').get();
  if (levelCount.count === 0) {
    const insertLevel = db.prepare('INSERT INTO training_levels (name, order_index, status) VALUES (?, ?, ?)');
    insertLevel.run('Basic', 1, 'active');
    insertLevel.run('Intermediate', 2, 'active');
    insertLevel.run('Advance', 3, 'active');

    // Seed default subjects for Basic
    const basicLevel = db.prepare('SELECT id FROM training_levels WHERE name = ?').get('Basic');
    const insertSubject = db.prepare('INSERT INTO subjects (level_id, name, is_required, status) VALUES (?, ?, ?, ?)');

    insertSubject.run(basicLevel.id, 'Basic Insurance Knowledge', 1, 'active');
    insertSubject.run(basicLevel.id, 'Product Knowledge', 1, 'active');
    insertSubject.run(basicLevel.id, 'Insurance Regulation & Compliance', 1, 'active');
    insertSubject.run(basicLevel.id, 'Basic Selling Skill', 1, 'active');

    // Seed default subjects for Intermediate
    const interLevel = db.prepare('SELECT id FROM training_levels WHERE name = ?').get('Intermediate');
    insertSubject.run(interLevel.id, 'Financial Planning Fundamentals', 1, 'active');
    insertSubject.run(interLevel.id, 'Objection Handling & Closing', 1, 'active');
    insertSubject.run(interLevel.id, 'Unit Link Mastery', 1, 'active');
    insertSubject.run(interLevel.id, 'Customer Relationship Management', 0, 'active'); // Optional

    // Seed default subjects for Advance
    const advLevel = db.prepare('SELECT id FROM training_levels WHERE name = ?').get('Advance');
    insertSubject.run(advLevel.id, 'High Net-Worth Client Strategy', 1, 'active');
    insertSubject.run(advLevel.id, 'Agency Building & Leadership', 1, 'active');
    insertSubject.run(advLevel.id, 'Estate Planning & Tax Law', 1, 'active');
    insertSubject.run(advLevel.id, 'Digital Branding for Top Producers', 0, 'active');

    // Seed sample training masters
    const subBasic1 = db.prepare('SELECT id FROM subjects WHERE name = ?').get('Basic Insurance Knowledge');
    const subBasic2 = db.prepare('SELECT id FROM subjects WHERE name = ?').get('Product Knowledge');
    const subBasic3 = db.prepare('SELECT id FROM subjects WHERE name = ?').get('Insurance Regulation & Compliance');
    const subBasic4 = db.prepare('SELECT id FROM subjects WHERE name = ?').get('Basic Selling Skill');

    const insertTraining = db.prepare('INSERT INTO trainings (code, name, subject_id, has_quiz, passing_grade, status) VALUES (?, ?, ?, ?, ?, ?)');
    insertTraining.run('TRN-BAS-01', 'Basic Insurance Foundation', subBasic1.id, 1, 75, 'active');
    insertTraining.run('TRN-BAS-02', 'Product Knowledge Masterclass', subBasic2.id, 1, 75, 'active');
    insertTraining.run('TRN-BAS-03', 'Insurance Code of Ethics & Regulation', subBasic3.id, 1, 75, 'active');
    insertTraining.run('TRN-BAS-04', 'Effective Selling & Prospecting', subBasic4.id, 0, 0, 'active'); // No quiz

    // Seed sample participants
    const insertParticipant = db.prepare('INSERT INTO participants (name, email, nik, phone, branch, status) VALUES (?, ?, ?, ?, ?, ?)');
    insertParticipant.run('Budi Santoso', 'budi.santoso@email.com', '3171012345670001', '081234567890', 'Jakarta Pusat', 'active');
    insertParticipant.run('Siti Rahmawati', 'siti.rahma@email.com', '3273012345670002', '081234567891', 'Bandung', 'active');
    insertParticipant.run('Andi Pratama', 'andi.pratama@email.com', '3578012345670003', '081234567892', 'Surabaya', 'active');
    insertParticipant.run('Dewi Lestari', 'dewi.lestari@email.com', '5171012345670004', '081234567893', 'Denpasar', 'active');
    insertParticipant.run('Rian Hidayat', 'rian.hidayat@email.com', '1271012345670005', '081234567894', 'Medan', 'active');

    // Seed sample sessions
    const trn1 = db.prepare('SELECT id FROM trainings WHERE code = ?').get('TRN-BAS-01');
    const trn2 = db.prepare('SELECT id FROM trainings WHERE code = ?').get('TRN-BAS-02');

    const insertSession = db.prepare('INSERT INTO training_sessions (training_id, batch_name, date, trainer, location, status, notes) VALUES (?, ?, ?, ?, ?, ?, ?)');
    const s1 = insertSession.run(trn1.id, 'Batch 01 - Jakarta', '2026-09-01', 'Coach Hendra Gunawan', 'Training Room Lt. 3 Jakarta', 'Completed', 'Pelaksanaan batch pertama sukses.');
    const s2 = insertSession.run(trn2.id, 'Batch 01 - Nasional Online', '2026-09-04', 'Coach Diana Putri', 'Virtual Zoom Room 1', 'Completed', 'Peserta aktif.');

    // Seed Session Participants & Attendance
    const pBudi = db.prepare('SELECT id FROM participants WHERE email = ?').get('budi.santoso@email.com');
    const pSiti = db.prepare('SELECT id FROM participants WHERE email = ?').get('siti.rahma@email.com');
    const pAndi = db.prepare('SELECT id FROM participants WHERE email = ?').get('andi.pratama@email.com');
    const pDewi = db.prepare('SELECT id FROM participants WHERE email = ?').get('dewi.lestari@email.com');

    const insertSessionPart = db.prepare('INSERT INTO session_participants (session_id, participant_id, attendance, status, completed_at) VALUES (?, ?, ?, ?, ?)');
    insertSessionPart.run(s1.lastInsertRowid, pBudi.id, 'Hadir', 'Completed', '2026-09-01 17:00:00');
    insertSessionPart.run(s1.lastInsertRowid, pSiti.id, 'Hadir', 'Completed', '2026-09-01 17:00:00');
    insertSessionPart.run(s1.lastInsertRowid, pAndi.id, 'Hadir', 'Completed', '2026-09-01 17:00:00');
    insertSessionPart.run(s1.lastInsertRowid, pDewi.id, 'Tidak Hadir', 'Completed', '2026-09-01 17:00:00');

    // Seed Quiz Scores
    const insertQuiz = db.prepare('INSERT INTO quiz_scores (session_id, participant_id, score, result) VALUES (?, ?, ?, ?)');
    insertQuiz.run(s1.lastInsertRowid, pBudi.id, 88, 'PASS');
    insertQuiz.run(s1.lastInsertRowid, pSiti.id, 92, 'PASS');
    insertQuiz.run(s1.lastInsertRowid, pAndi.id, 65, 'FAIL');

    // Add participants to session 2
    insertSessionPart.run(s2.lastInsertRowid, pBudi.id, 'Hadir', 'Completed', '2026-09-04 17:00:00');
    insertSessionPart.run(s2.lastInsertRowid, pSiti.id, 'Hadir', 'Completed', '2026-09-04 17:00:00');
    insertQuiz.run(s2.lastInsertRowid, pBudi.id, 85, 'PASS');
    insertQuiz.run(s2.lastInsertRowid, pSiti.id, 95, 'PASS');
  }
}

function resetDbConnection() {
  if (db) {
    try {
      db.close();
    } catch (e) {
      console.error('Error closing db:', e);
    }
  }
  db = new Database(dbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  return db;
}

module.exports = {
  getDb,
  initDb,
  resetDbConnection,
  dbPath,
  backupsDir
};

const { getDb } = require('../db/database');

/**
 * Get all subjects with completion status for a specific participant
 */
function getParticipantSubjectsStatus(participantId) {
  const db = getDb();

  // Get all active levels and their active subjects
  const subjects = db.prepare(`
    SELECT 
      s.id as subject_id,
      s.name as subject_name,
      s.is_required,
      s.level_id,
      tl.name as level_name,
      tl.order_index as level_order
    FROM subjects s
    JOIN training_levels tl ON s.level_id = tl.id
    WHERE s.status = 'active' AND tl.status = 'active'
    ORDER BY tl.order_index ASC, s.id ASC
  `).all();

  // Get all training sessions attended by this participant with quiz results
  const completedTrainings = db.prepare(`
    SELECT 
      t.subject_id,
      t.id as training_id,
      t.name as training_name,
      t.has_quiz,
      t.passing_grade,
      sp.attendance,
      sp.completed_at,
      ts.batch_name,
      ts.date as session_date,
      qs.score as quiz_score,
      qs.result as quiz_result
    FROM session_participants sp
    JOIN training_sessions ts ON sp.session_id = ts.id
    JOIN trainings t ON ts.training_id = t.id
    LEFT JOIN quiz_scores qs ON qs.session_id = sp.session_id AND qs.participant_id = sp.participant_id
    WHERE sp.participant_id = ? AND sp.attendance = 'Hadir'
  `).all(participantId);

  // Group completed trainings by subject_id
  const subjectTrainingsMap = {};
  for (const trn of completedTrainings) {
    if (!subjectTrainingsMap[trn.subject_id]) {
      subjectTrainingsMap[trn.subject_id] = [];
    }
    subjectTrainingsMap[trn.subject_id].push(trn);
  }

  // Determine completion for each subject according to PRD Rule MVP
  const evaluatedSubjects = subjects.map(sub => {
    const trainingsAttended = subjectTrainingsMap[sub.subject_id] || [];

    // Check if at least one training meets completion criteria:
    // 1) If training has no quiz: Attendance == 'Hadir' -> Completed
    // 2) If training has quiz: Attendance == 'Hadir' AND Quiz Result == 'PASS' -> Completed
    let isCompleted = false;
    let qualifyingTraining = null;

    for (const t of trainingsAttended) {
      if (t.has_quiz === 0) {
        isCompleted = true;
        qualifyingTraining = t;
        break;
      } else if (t.has_quiz === 1 && t.quiz_result === 'PASS') {
        isCompleted = true;
        qualifyingTraining = t;
        break;
      }
    }

    return {
      subject_id: sub.subject_id,
      subject_name: sub.subject_name,
      is_required: Boolean(sub.is_required),
      level_id: sub.level_id,
      level_name: sub.level_name,
      level_order: sub.level_order,
      is_completed: isCompleted,
      qualifying_training: qualifyingTraining,
      all_attempts: trainingsAttended
    };
  });

  return evaluatedSubjects;
}

/**
 * Get Level Progress & Status for a specific participant
 */
function getParticipantLevelProgress(participantId) {
  const db = getDb();
  const evaluatedSubjects = getParticipantSubjectsStatus(participantId);

  // Get all active levels
  const levels = db.prepare(`
    SELECT id, name, order_index
    FROM training_levels
    WHERE status = 'active'
    ORDER BY order_index ASC
  `).all();

  const progressByLevel = levels.map(lvl => {
    const levelSubjects = evaluatedSubjects.filter(s => s.level_id === lvl.id);
    const requiredSubjects = levelSubjects.filter(s => s.is_required);
    const completedRequiredSubjects = requiredSubjects.filter(s => s.is_completed);

    const totalRequired = requiredSubjects.length;
    const completedCount = completedRequiredSubjects.length;

    const percentage = totalRequired > 0 
      ? Math.round((completedCount / totalRequired) * 100) 
      : 0;

    let status = 'Belum Mulai';
    if (completedCount === totalRequired && totalRequired > 0) {
      status = 'Lulus';
    } else if (completedCount > 0) {
      status = 'In Progress';
    }

    return {
      level_id: lvl.id,
      level_name: lvl.name,
      order_index: lvl.order_index,
      total_subjects: levelSubjects.length,
      total_required: totalRequired,
      completed_required: completedCount,
      percentage: percentage,
      status: status, // 'Belum Mulai' | 'In Progress' | 'Lulus'
      subjects: levelSubjects
    };
  });

  return progressByLevel;
}

/**
 * Get Full Agent Profile with Progress & Training History
 */
function getAgentDetailedProfile(participantId) {
  const db = getDb();
  const participant = db.prepare('SELECT * FROM participants WHERE id = ?').get(participantId);
  if (!participant) return null;

  const levelProgress = getParticipantLevelProgress(participantId);

  // Get full training history
  const history = db.prepare(`
    SELECT 
      ts.date as session_date,
      t.name as training_name,
      t.code as training_code,
      s.name as subject_name,
      tl.name as level_name,
      ts.batch_name,
      ts.trainer,
      ts.location,
      sp.attendance,
      t.has_quiz,
      t.passing_grade,
      qs.score as quiz_score,
      qs.result as quiz_result,
      sp.completed_at
    FROM session_participants sp
    JOIN training_sessions ts ON sp.session_id = ts.id
    JOIN trainings t ON ts.training_id = t.id
    JOIN subjects s ON t.subject_id = s.id
    JOIN training_levels tl ON s.level_id = tl.id
    LEFT JOIN quiz_scores qs ON qs.session_id = sp.session_id AND qs.participant_id = sp.participant_id
    WHERE sp.participant_id = ?
    ORDER BY ts.date DESC, sp.id DESC
  `).all(participantId);

  // Overall metrics for agent
  const quizStats = db.prepare(`
    SELECT 
      COUNT(score) as total_quiz,
      AVG(score) as avg_score,
      MAX(score) as max_score
    FROM quiz_scores
    WHERE participant_id = ?
  `).get(participantId);

  return {
    participant,
    level_progress: levelProgress,
    training_history: history,
    quiz_stats: {
      total_quiz: quizStats.total_quiz || 0,
      avg_score: quizStats.avg_score ? parseFloat(quizStats.avg_score.toFixed(1)) : 0,
      max_score: quizStats.max_score || 0
    }
  };
}

/**
 * Get Leaderboard & Ranking with Filters
 */
function getRankings(filters = {}) {
  const db = getDb();
  const { training_id, level_id, branch, limit = 100 } = filters;

  let query = `
    SELECT 
      p.id as participant_id,
      p.name,
      p.email,
      p.nik,
      p.phone,
      p.branch,
      COUNT(qs.id) as total_quiz,
      AVG(qs.score) as average_score,
      MAX(qs.score) as highest_score,
      SUM(CASE WHEN qs.result = 'PASS' THEN 1 ELSE 0 END) as passed_quiz_count
    FROM participants p
    JOIN quiz_scores qs ON qs.participant_id = p.id
    JOIN training_sessions ts ON qs.session_id = ts.id
    JOIN trainings t ON ts.training_id = t.id
    JOIN subjects s ON t.subject_id = s.id
    WHERE p.status = 'active'
  `;

  const params = [];

  if (training_id) {
    query += ` AND t.id = ?`;
    params.push(training_id);
  }

  if (level_id) {
    query += ` AND s.level_id = ?`;
    params.push(level_id);
  }

  if (branch) {
    query += ` AND p.branch = ?`;
    params.push(branch);
  }

  query += `
    GROUP BY p.id
    HAVING COUNT(qs.id) > 0
    ORDER BY average_score DESC, total_quiz DESC, p.name ASC
    LIMIT ?
  `;
  params.push(parseInt(limit, 10));

  const rows = db.prepare(query).all(...params);

  // Assign ranks with 1-based index
  return rows.map((row, idx) => ({
    rank: idx + 1,
    participant_id: row.participant_id,
    name: row.name,
    email: row.email,
    nik: row.nik,
    phone: row.phone,
    branch: row.branch || '-',
    total_quiz: row.total_quiz,
    average_score: parseFloat(row.average_score.toFixed(1)),
    highest_score: row.highest_score,
    passed_quiz_count: row.passed_quiz_count
  }));
}

/**
 * Get Dashboard Overall Statistics
 */
function getDashboardStats() {
  const db = getDb();

  const totalPeserta = db.prepare(`SELECT COUNT(*) as count FROM participants WHERE status = 'active'`).get().count;
  const totalTraining = db.prepare(`SELECT COUNT(*) as count FROM trainings WHERE status = 'active'`).get().count;
  const totalPelaksanaan = db.prepare(`SELECT COUNT(*) as count FROM training_sessions`).get().count;

  const quizSummary = db.prepare(`
    SELECT 
      COUNT(*) as total_quiz,
      AVG(score) as avg_score,
      SUM(CASE WHEN result = 'PASS' THEN 1 ELSE 0 END) as passed_count
    FROM quiz_scores
  `).get();

  // Level graduation distribution across all active participants
  const allParticipants = db.prepare(`SELECT id FROM participants WHERE status = 'active'`).all();
  const levels = db.prepare(`SELECT id, name, order_index FROM training_levels WHERE status = 'active' ORDER BY order_index ASC`).all();

  const levelStatsMap = {};
  levels.forEach(lvl => {
    levelStatsMap[lvl.name] = {
      level_id: lvl.id,
      level_name: lvl.name,
      lulus: 0,
      in_progress: 0,
      belum_mulai: 0,
      total: allParticipants.length
    };
  });

  for (const p of allParticipants) {
    const progressList = getParticipantLevelProgress(p.id);
    for (const prog of progressList) {
      if (levelStatsMap[prog.level_name]) {
        if (prog.status === 'Lulus') {
          levelStatsMap[prog.level_name].lulus += 1;
        } else if (prog.status === 'In Progress') {
          levelStatsMap[prog.level_name].in_progress += 1;
        } else {
          levelStatsMap[prog.level_name].belum_mulai += 1;
        }
      }
    }
  }

  // Most attended trainings
  const mostAttended = db.prepare(`
    SELECT 
      t.id,
      t.name as training_name,
      t.code as training_code,
      COUNT(sp.id) as total_attendees,
      COUNT(DISTINCT ts.id) as total_batches
    FROM trainings t
    JOIN training_sessions ts ON ts.training_id = t.id
    JOIN session_participants sp ON sp.session_id = ts.id AND sp.attendance = 'Hadir'
    GROUP BY t.id
    ORDER BY total_attendees DESC
    LIMIT 5
  `).all();

  // Branch statistics
  const branchStats = db.prepare(`
    SELECT 
      COALESCE(branch, 'Belum Ditentukan') as branch_name,
      COUNT(*) as participant_count
    FROM participants
    WHERE status = 'active'
    GROUP BY branch
    ORDER BY participant_count DESC
    LIMIT 6
  `).all();

  return {
    summary: {
      total_peserta: totalPeserta,
      total_training: totalTraining,
      total_pelaksanaan: totalPelaksanaan,
      total_quiz: quizSummary.total_quiz || 0,
      average_score: quizSummary.avg_score ? parseFloat(quizSummary.avg_score.toFixed(1)) : 0,
      passed_rate: quizSummary.total_quiz > 0 
        ? Math.round((quizSummary.passed_count / quizSummary.total_quiz) * 100) 
        : 0
    },
    level_distribution: Object.values(levelStatsMap),
    most_attended_trainings: mostAttended,
    branch_distribution: branchStats
  };
}

module.exports = {
  getParticipantSubjectsStatus,
  getParticipantLevelProgress,
  getAgentDetailedProfile,
  getRankings,
  getDashboardStats
};

const { getDb } = require('../db/database');

/**
 * Parses raw text lines from Excel/CSV copy-paste.
 * Supports Tab-separated, Comma-separated, or semicolon-separated values.
 */
function parseRawLines(rawText) {
  if (!rawText || typeof rawText !== 'string') return [];

  const lines = rawText.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
  const rows = [];

  for (const line of lines) {
    let tokens = [];
    if (line.includes('\t')) {
      tokens = line.split('\t').map(t => t.trim());
    } else if (line.includes(',')) {
      tokens = line.split(',').map(t => t.trim());
    } else if (line.includes(';')) {
      tokens = line.split(';').map(t => t.trim());
    } else {
      // Space separated or single item
      tokens = line.split(/\s+/).map(t => t.trim());
    }
    rows.push(tokens.filter(t => t.length > 0));
  }

  return rows;
}

/**
 * Validate & Preview Import Peserta (Copy-Paste)
 */
function previewImportParticipants(rawText) {
  const db = getDb();
  const rows = parseRawLines(rawText);
  const existingEmails = new Set(db.prepare('SELECT email FROM participants').all().map(p => p.email.toLowerCase()));

  const seenInPaste = new Set();
  const results = [];

  for (let i = 0; i < rows.length; i++) {
    const tokens = rows[i];

    // Ignore header row if it contains 'email' or 'nama'
    if (i === 0 && (tokens[0].toLowerCase() === 'email' || tokens[0].toLowerCase() === 'nama' || tokens[0].toLowerCase() === 'name')) {
      continue;
    }

    let email = '';
    let name = '';
    let nik = '';
    let phone = '';
    let branch = '';

    // If first token is email or looks like email
    if (tokens[0] && tokens[0].includes('@')) {
      email = tokens[0];
      name = tokens[1] || email.split('@')[0];
      nik = tokens[2] || '';
      phone = tokens[3] || '';
      branch = tokens[4] || '';
    } else if (tokens[1] && tokens[1].includes('@')) {
      name = tokens[0];
      email = tokens[1];
      nik = tokens[2] || '';
      phone = tokens[3] || '';
      branch = tokens[4] || '';
    } else {
      email = tokens[0] || '';
      name = tokens[1] || email;
    }

    email = email.trim().toLowerCase();
    name = name.trim();

    const errors = [];

    if (!email) {
      errors.push('Email wajib diisi.');
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      errors.push('Format email tidak valid.');
    } else if (existingEmails.has(email)) {
      errors.push('Email sudah terdaftar di database.');
    } else if (seenInPaste.has(email)) {
      errors.push('Email duplikat di dalam data paste.');
    }

    if (!name) {
      errors.push('Nama peserta wajib diisi.');
    }

    const isValid = errors.length === 0;
    if (isValid) {
      seenInPaste.add(email);
    }

    results.push({
      line_number: i + 1,
      email,
      name,
      nik,
      phone,
      branch,
      status: isValid ? 'VALID' : 'INVALID',
      errors: errors
    });
  }

  const validCount = results.filter(r => r.status === 'VALID').length;
  const invalidCount = results.filter(r => r.status === 'INVALID').length;

  return {
    total_rows: results.length,
    valid_count: validCount,
    invalid_count: invalidCount,
    items: results
  };
}

/**
 * Execute Commit Import Peserta
 */
function executeImportParticipants(validItems) {
  const db = getDb();
  const insertStmt = db.prepare(`
    INSERT INTO participants (name, email, nik, phone, branch, status)
    VALUES (?, ?, ?, ?, ?, 'active')
  `);

  const insertTransaction = db.transaction((items) => {
    let inserted = 0;
    for (const item of items) {
      insertStmt.run(item.name, item.email.toLowerCase(), item.nik || null, item.phone || null, item.branch || null);
      inserted++;
    }
    return inserted;
  });

  return insertTransaction(validItems);
}

/**
 * Validate & Preview Import Quiz Scores for a Session (Copy-Paste)
 */
function previewImportQuizScores(sessionId, rawText) {
  const db = getDb();
  const session = db.prepare(`
    SELECT ts.*, t.name as training_name, t.has_quiz, t.passing_grade 
    FROM training_sessions ts
    JOIN trainings t ON ts.training_id = t.id
    WHERE ts.id = ?
  `).get(sessionId);

  if (!session) {
    throw new Error('Sesi pelaksanaan training tidak ditemukan.');
  }

  const passingGrade = session.passing_grade || 75;
  const rows = parseRawLines(rawText);

  // Get all registered participants in this session
  const registeredParticipants = db.prepare(`
    SELECT p.id, p.name, p.email, sp.attendance 
    FROM session_participants sp
    JOIN participants p ON sp.participant_id = p.id
    WHERE sp.session_id = ?
  `).all(sessionId);

  const participantByEmail = new Map();
  registeredParticipants.forEach(p => participantByEmail.set(p.email.toLowerCase(), p));

  // Also check if email exists in global participants table for clearer error messaging
  const allParticipants = db.prepare('SELECT id, name, email FROM participants').all();
  const globalParticipantsMap = new Map();
  allParticipants.forEach(p => globalParticipantsMap.set(p.email.toLowerCase(), p));

  const seenEmails = new Set();
  const results = [];

  for (let i = 0; i < rows.length; i++) {
    const tokens = rows[i];

    // Ignore header row if 'email' / 'nilai' / 'score'
    if (i === 0 && (tokens[0].toLowerCase().includes('email') || tokens[0].toLowerCase().includes('nilai') || tokens[0].toLowerCase().includes('score'))) {
      continue;
    }

    let email = tokens[0] || '';
    let scoreStr = tokens[1] !== undefined ? tokens[1] : '';

    // If first column is number and second is email
    if (!isNaN(parseFloat(tokens[0])) && tokens[1] && tokens[1].includes('@')) {
      scoreStr = tokens[0];
      email = tokens[1];
    }

    email = email.trim().toLowerCase();
    scoreStr = String(scoreStr).trim().replace(',', '.');

    const errors = [];
    let score = null;
    let participant = null;
    let resultStatus = null;

    if (!email) {
      errors.push('Email kosong.');
    } else if (!globalParticipantsMap.has(email)) {
      errors.push('Email tidak ditemukan di master database peserta.');
    } else if (!participantByEmail.has(email)) {
      errors.push('Peserta tidak terdaftar di sesi/batch ini.');
    } else {
      participant = participantByEmail.get(email);
    }

    if (seenEmails.has(email)) {
      errors.push('Email duplikat di data paste.');
    }

    if (scoreStr === '') {
      errors.push('Nilai quiz kosong.');
    } else {
      score = parseFloat(scoreStr);
      if (isNaN(score) || score < 0 || score > 100) {
        errors.push('Nilai harus berupa angka antara 0 - 100.');
      }
    }

    const isValid = errors.length === 0;
    if (isValid) {
      seenEmails.add(email);
      resultStatus = score >= passingGrade ? 'PASS' : 'FAIL';
    }

    results.push({
      line_number: i + 1,
      email,
      participant_id: participant ? participant.id : null,
      participant_name: participant ? participant.name : (globalParticipantsMap.get(email)?.name || '-'),
      score: isValid ? score : scoreStr,
      passing_grade: passingGrade,
      result: resultStatus,
      status: isValid ? 'VALID' : 'INVALID',
      errors: errors
    });
  }

  const validCount = results.filter(r => r.status === 'VALID').length;
  const invalidCount = results.filter(r => r.status === 'INVALID').length;

  return {
    session_info: {
      session_id: session.id,
      batch_name: session.batch_name,
      training_name: session.training_name,
      passing_grade: passingGrade
    },
    total_rows: results.length,
    valid_count: validCount,
    invalid_count: invalidCount,
    items: results
  };
}

/**
 * Execute Commit Import Quiz Scores
 */
function executeImportQuizScores(sessionId, validItems) {
  const db = getDb();

  const upsertQuiz = db.prepare(`
    INSERT INTO quiz_scores (session_id, participant_id, score, result)
    VALUES (?, ?, ?, ?)
    ON CONFLICT(session_id, participant_id) DO UPDATE SET
      score = excluded.score,
      result = excluded.result,
      created_at = CURRENT_TIMESTAMP
  `);

  const updateAttendanceIfPassed = db.prepare(`
    UPDATE session_participants
    SET attendance = 'Hadir', status = 'Completed', completed_at = CURRENT_TIMESTAMP
    WHERE session_id = ? AND participant_id = ?
  `);

  const transaction = db.transaction((items) => {
    let saved = 0;
    for (const item of items) {
      upsertQuiz.run(sessionId, item.participant_id, item.score, item.result);
      // Ensure attendance is marked Hadir
      updateAttendanceIfPassed.run(sessionId, item.participant_id);
      saved++;
    }
    return saved;
  });

  return transaction(validItems);
}

/**
 * Batch Add Participants to a Session (Paste emails)
 */
function previewBatchAddParticipants(sessionId, rawText) {
  const db = getDb();
  const session = db.prepare('SELECT id, batch_name FROM training_sessions WHERE id = ?').get(sessionId);
  if (!session) throw new Error('Sesi training tidak ditemukan.');

  const rows = parseRawLines(rawText);
  const allParticipants = db.prepare('SELECT id, name, email, branch FROM participants WHERE status = "active"').all();
  const participantMap = new Map();
  allParticipants.forEach(p => participantMap.set(p.email.toLowerCase(), p));

  const alreadyRegistered = new Set(
    db.prepare('SELECT p.email FROM session_participants sp JOIN participants p ON sp.participant_id = p.id WHERE sp.session_id = ?')
      .all(sessionId)
      .map(r => r.email.toLowerCase())
  );

  const seenInPaste = new Set();
  const results = [];

  for (let i = 0; i < rows.length; i++) {
    const email = (rows[i][0] || '').toLowerCase().trim();
    if (!email) continue;
    if (i === 0 && (email === 'email' || email === 'peserta')) continue;

    const errors = [];
    let p = participantMap.get(email);

    if (!p) {
      errors.push('Email tidak ditemukan di master data peserta aktif.');
    } else if (alreadyRegistered.has(email)) {
      errors.push('Peserta sudah terdaftar di batch ini.');
    } else if (seenInPaste.has(email)) {
      errors.push('Email duplikat dalam data input.');
    }

    const isValid = errors.length === 0;
    if (isValid) {
      seenInPaste.add(email);
    }

    results.push({
      line_number: i + 1,
      email,
      participant_id: p ? p.id : null,
      name: p ? p.name : '-',
      branch: p ? p.branch : '-',
      status: isValid ? 'VALID' : 'INVALID',
      errors: errors
    });
  }

  return {
    total_rows: results.length,
    valid_count: results.filter(r => r.status === 'VALID').length,
    invalid_count: results.filter(r => r.status === 'INVALID').length,
    items: results
  };
}

function executeBatchAddParticipants(sessionId, validItems) {
  const db = getDb();
  const insertStmt = db.prepare(`
    INSERT OR IGNORE INTO session_participants (session_id, participant_id, attendance, status)
    VALUES (?, ?, 'Belum', 'Registered')
  `);

  const transaction = db.transaction((items) => {
    let added = 0;
    for (const item of items) {
      if (item.participant_id) {
        insertStmt.run(sessionId, item.participant_id);
        added++;
      }
    }
    return added;
  });

  return transaction(validItems);
}

module.exports = {
  previewImportParticipants,
  executeImportParticipants,
  previewImportQuizScores,
  executeImportQuizScores,
  previewBatchAddParticipants,
  executeBatchAddParticipants
};

const fs = require('fs');
const path = require('path');
const { getDb, dbPath, backupsDir, resetDbConnection } = require('../db/database');
const { getRankings } = require('./calculationService');

/**
 * Create a timestamped backup of the SQLite database
 */
function createBackup() {
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-').replace('T', '_').slice(0, 19);
  const backupFileName = `backup_training_agency_${timestamp}.db`;
  const destinationPath = path.join(backupsDir, backupFileName);

  const db = getDb();
  // Use better-sqlite3 backup API for safe hot backup
  db.backup(destinationPath);

  const stats = fs.statSync(destinationPath);

  return {
    filename: backupFileName,
    path: destinationPath,
    size_bytes: stats.size,
    size_formatted: `${(stats.size / 1024).toFixed(1)} KB`,
    created_at: new Date().toISOString()
  };
}

/**
 * List available backups in the backups directory
 */
function listBackups() {
  if (!fs.existsSync(backupsDir)) {
    return [];
  }

  const files = fs.readdirSync(backupsDir).filter(f => f.endsWith('.db'));
  const backups = files.map(file => {
    const filePath = path.join(backupsDir, file);
    const stats = fs.statSync(filePath);
    return {
      filename: file,
      size_bytes: stats.size,
      size_formatted: `${(stats.size / 1024).toFixed(1)} KB`,
      created_at: stats.birthtime || stats.mtime
    };
  });

  // Sort descending by creation date
  backups.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
  return backups;
}

/**
 * Restore database from an existing backup filename or path
 */
function restoreBackup(backupFilename) {
  const sourcePath = path.isAbsolute(backupFilename)
    ? backupFilename
    : path.join(backupsDir, backupFilename);

  if (!fs.existsSync(sourcePath)) {
    throw new Error('File backup tidak ditemukan.');
  }

  // Create an automatic safety backup before restoring
  createBackup();

  // Reset database connection and copy file
  resetDbConnection();
  fs.copyFileSync(sourcePath, dbPath);
  resetDbConnection();

  return {
    success: true,
    message: `Database berhasil direstore dari file ${path.basename(sourcePath)}`
  };
}

/**
 * Helper to escape CSV cell
 */
function escapeCsv(value) {
  if (value === null || value === undefined) return '""';
  const str = String(value).replace(/"/g, '""');
  return `"${str}"`;
}

/**
 * Export Participants to CSV
 */
function exportParticipantsCsv() {
  const db = getDb();
  const participants = db.prepare(`
    SELECT id, name, email, nik, phone, branch, status, created_at 
    FROM participants 
    ORDER BY name ASC
  `).all();

  const headers = ['ID', 'Nama', 'Email', 'NIK', 'No_HP', 'Cabang', 'Status', 'Tanggal_Daftar'];
  const rows = participants.map(p => [
    escapeCsv(p.id),
    escapeCsv(p.name),
    escapeCsv(p.email),
    escapeCsv(p.nik || ''),
    escapeCsv(p.phone || ''),
    escapeCsv(p.branch || ''),
    escapeCsv(p.status),
    escapeCsv(p.created_at)
  ].join(','));

  return [headers.join(','), ...rows].join('\r\n');
}

/**
 * Export Rankings to CSV
 */
function exportRankingsCsv(filters = {}) {
  const rankings = getRankings({ ...filters, limit: 10000 });

  const headers = ['Peringkat', 'Nama', 'Email', 'Cabang', 'Total_Quiz', 'Nilai_Rata_Rata', 'Nilai_Tertinggi', 'Quiz_Lulus'];
  const rows = rankings.map(r => [
    escapeCsv(r.rank),
    escapeCsv(r.name),
    escapeCsv(r.email),
    escapeCsv(r.branch),
    escapeCsv(r.total_quiz),
    escapeCsv(r.average_score),
    escapeCsv(r.highest_score),
    escapeCsv(r.passed_quiz_count)
  ].join(','));

  return [headers.join(','), ...rows].join('\r\n');
}

/**
 * Export Training History & Attendance to CSV
 */
function exportTrainingHistoryCsv() {
  const db = getDb();
  const history = db.prepare(`
    SELECT 
      ts.date as session_date,
      ts.batch_name,
      t.code as training_code,
      t.name as training_name,
      s.name as subject_name,
      tl.name as level_name,
      p.name as participant_name,
      p.email as participant_email,
      p.branch,
      sp.attendance,
      t.has_quiz,
      t.passing_grade,
      qs.score as quiz_score,
      qs.result as quiz_result
    FROM session_participants sp
    JOIN training_sessions ts ON sp.session_id = ts.id
    JOIN trainings t ON ts.training_id = t.id
    JOIN subjects s ON t.subject_id = s.id
    JOIN training_levels tl ON s.level_id = tl.id
    JOIN participants p ON sp.participant_id = p.id
    LEFT JOIN quiz_scores qs ON qs.session_id = sp.session_id AND qs.participant_id = sp.participant_id
    ORDER BY ts.date DESC, t.name ASC, p.name ASC
  `).all();

  const headers = [
    'Tanggal', 'Batch', 'Kode_Training', 'Nama_Training', 'Subject', 'Level',
    'Nama_Peserta', 'Email_Peserta', 'Cabang', 'Kehadiran',
    'Ada_Quiz', 'Passing_Grade', 'Nilai_Quiz', 'Hasil_Quiz'
  ];

  const rows = history.map(h => [
    escapeCsv(h.session_date),
    escapeCsv(h.batch_name),
    escapeCsv(h.training_code || ''),
    escapeCsv(h.training_name),
    escapeCsv(h.subject_name),
    escapeCsv(h.level_name),
    escapeCsv(h.participant_name),
    escapeCsv(h.participant_email),
    escapeCsv(h.branch || ''),
    escapeCsv(h.attendance),
    escapeCsv(h.has_quiz ? 'Ya' : 'Tidak'),
    escapeCsv(h.passing_grade || ''),
    escapeCsv(h.quiz_score !== null ? h.quiz_score : ''),
    escapeCsv(h.quiz_result || '')
  ].join(','));

  return [headers.join(','), ...rows].join('\r\n');
}

module.exports = {
  createBackup,
  listBackups,
  restoreBackup,
  exportParticipantsCsv,
  exportRankingsCsv,
  exportTrainingHistoryCsv
};

const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const { getDb } = require('../db/database');

const JWT_SECRET = process.env.JWT_SECRET || 'training_agency_mvp_secret_key_2026';

function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Akses ditolak. Token tidak ditemukan.' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.admin = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Token tidak valid atau telah kedaluwarsa.' });
  }
}

router.post('/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Username dan password wajib diisi.' });
  }

  const db = getDb();
  const admin = db.prepare('SELECT * FROM admins WHERE username = ?').get(username);
  if (!admin) {
    return res.status(401).json({ error: 'Username atau password salah.' });
  }

  const isMatch = bcrypt.compareSync(password, admin.password_hash);
  if (!isMatch) {
    return res.status(401).json({ error: 'Username atau password salah.' });
  }

  const token = jwt.sign(
    { id: admin.id, username: admin.username, name: admin.name },
    JWT_SECRET,
    { expiresIn: '7d' }
  );

  res.json({
    token,
    admin: {
      id: admin.id,
      username: admin.username,
      name: admin.name
    }
  });
});

router.get('/me', authMiddleware, (req, res) => {
  const db = getDb();
  const admin = db.prepare('SELECT id, username, name, created_at FROM admins WHERE id = ?').get(req.admin.id);
  if (!admin) {
    return res.status(404).json({ error: 'Akun admin tidak ditemukan.' });
  }
  res.json({ admin });
});

router.post('/change-password', authMiddleware, (req, res) => {
  const { current_password, new_password } = req.body;
  if (!current_password || !new_password) {
    return res.status(400).json({ error: 'Password saat ini dan password baru wajib diisi.' });
  }

  const db = getDb();
  const admin = db.prepare('SELECT * FROM admins WHERE id = ?').get(req.admin.id);
  if (!admin || !bcrypt.compareSync(current_password, admin.password_hash)) {
    return res.status(400).json({ error: 'Password saat ini tidak sesuai.' });
  }

  const salt = bcrypt.genSaltSync(10);
  const newHash = bcrypt.hashSync(new_password, salt);
  db.prepare('UPDATE admins SET password_hash = ? WHERE id = ?').run(newHash, admin.id);

  res.json({ success: true, message: 'Password berhasil diperbarui.' });
});

module.exports = {
  router,
  authMiddleware
};

