// --- LEVELS ---

router.get('/levels', authMiddleware, (req, res) => {
  const db = getDb();
  const levels = db.prepare(`
    SELECT 
      l.*,
      COUNT(s.id) as total_subjects,
      SUM(CASE WHEN s.is_required = 1 AND s.status = 'active' THEN 1 ELSE 0 END) as total_required_subjects
    FROM training_levels l
    LEFT JOIN subjects s ON s.level_id = l.id
    GROUP BY l.id
    ORDER BY l.order_index ASC
  `).all();
  res.json(levels);
});

router.post('/levels', authMiddleware, (req, res) => {
  const { name, order_index, status = 'active' } = req.body;
  if (!name) return res.status(400).json({ error: 'Nama level wajib diisi.' });

  const db = getDb();
  try {
    const nextOrder = order_index || (db.prepare('SELECT MAX(order_index) as max_order FROM training_levels').get().max_order || 0) + 1;
    const stmt = db.prepare('INSERT INTO training_levels (name, order_index, status) VALUES (?, ?, ?)');
    const info = stmt.run(name.trim(), nextOrder, status);
    res.json({ id: info.lastInsertRowid, name, order_index: nextOrder, status });
  } catch (err) {
    if (err.message.includes('UNIQUE')) {
      return res.status(400).json({ error: 'Level dengan nama ini sudah ada.' });
    }
    res.status(500).json({ error: err.message });
  }
});

router.put('/levels/:id', authMiddleware, (req, res) => {
  const { name, order_index, status } = req.body;
  const db = getDb();
  try {
    db.prepare(`
      UPDATE training_levels 
      SET name = COALESCE(?, name),
          order_index = COALESCE(?, order_index),
          status = COALESCE(?, status)
      WHERE id = ?
    `).run(name ? name.trim() : null, order_index, status, req.params.id);
    res.json({ success: true, message: 'Level berhasil diperbarui.' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

router.delete('/levels/:id', authMiddleware, (req, res) => {
  const db = getDb();
  const subjectCount = db.prepare('SELECT COUNT(*) as count FROM subjects WHERE level_id = ?').get(req.params.id);
  if (subjectCount.count > 0) {
    return res.status(400).json({ error: 'Tidak dapat menghapus level yang masih memiliki subject/materi.' });
  }
  db.prepare('DELETE FROM training_levels WHERE id = ?').run(req.params.id);
  res.json({ success: true, message: 'Level berhasil dihapus.' });
});

