const { authMiddleware } = require('./auth');
const { getDb } = require('../db/database');
const { 
  previewImportQuizScores, 
  executeImportQuizScores, 
  previewBatchAddParticipants, 
  executeBatchAddParticipants 
} = require('../services/importService');

// ==========================================
// TRAINING MASTER
// ==========================================

router.get('/trainings', authMiddleware, (req, res) => {
  const { subject_id, level_id } = req.query;
  const db = getDb();
  let query = `
    SELECT 
      t.*,
      s.name as subject_name,
      s.is_required as subject_is_required,
      tl.id as level_id,
      tl.name as level_name,
      COUNT(ts.id) as total_sessions
    FROM trainings t
    JOIN subjects s ON t.subject_id = s.id
    JOIN training_levels tl ON s.level_id = tl.id
  `;
  const params = [];
  const conditions = [];

  if (subject_id) {
    conditions.push('t.subject_id = ?');
    params.push(subject_id);
  }
  if (level_id) {
    conditions.push('tl.id = ?');
    params.push(level_id);
  }

  if (conditions.length > 0) {
    query += ' WHERE ' + conditions.join(' AND ');
  }

  query += ' GROUP BY t.id ORDER BY tl.order_index ASC, t.id ASC';

  const trainings = db.prepare(query).all(...params);
  res.json(trainings);
});

router.post('/trainings', authMiddleware, (req, res) => {
  const { code, name, subject_id, has_quiz = 1, passing_grade = 75, status = 'active' } = req.body;
  if (!name || !subject_id) {
    return res.status(400).json({ error: 'Nama training dan Subject wajib diisi.' });
  }

  const db = getDb();
  try {
    const stmt = db.prepare(`
      INSERT INTO trainings (code, name, subject_id, has_quiz, passing_grade, status)
      VALUES (?, ?, ?, ?, ?, ?)
    `);
    const info = stmt.run(code ? code.trim() : null, name.trim(), subject_id, has_quiz ? 1 : 0, has_quiz ? (passing_grade || 75) : 0, status);
    res.json({ id: info.lastInsertRowid, message: 'Training Master berhasil ditambahkan.' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

router.put('/trainings/:id', authMiddleware, (req, res) => {
  const { code, name, subject_id, has_quiz, passing_grade, status } = req.body;
