  try {
    db.prepare(`
      UPDATE trainings
      SET code = COALESCE(?, code),
          name = COALESCE(?, name),
          subject_id = COALESCE(?, subject_id),
          has_quiz = COALESCE(?, has_quiz),
          passing_grade = COALESCE(?, passing_grade),
          status = COALESCE(?, status)
      WHERE id = ?
    `).run(
      code !== undefined ? (code ? code.trim() : null) : null,
      name ? name.trim() : null,
