router.get('/sessions', authMiddleware, (req, res) => {
  const { training_id, status } = req.query;
  const db = getDb();
  let query = `
    SELECT 
      ts.*,
      t.name as training_name,
      t.code as training_code,
      t.has_quiz,
      t.passing_grade,
      s.name as subject_name,
      tl.name as level_name,
      COUNT(sp.id) as total_participants,
      SUM(CASE WHEN sp.attendance = 'Hadir' THEN 1 ELSE 0 END) as attended_count,
      COUNT(qs.id) as quiz_submitted_count,
      SUM(CASE WHEN qs.result = 'PASS' THEN 1 ELSE 0 END) as passed_count
    FROM training_sessions ts
    JOIN trainings t ON ts.training_id = t.id
    JOIN subjects s ON t.subject_id = s.id
    JOIN training_levels tl ON s.level_id = tl.id
    LEFT JOIN session_participants sp ON sp.session_id = ts.id
    LEFT JOIN quiz_scores qs ON qs.session_id = ts.id AND qs.participant_id = sp.participant_id
  `;
  const params = [];
  const conditions = [];

  if (training_id) {
    conditions.push('ts.training_id = ?');
    params.push(training_id);
  }
  if (status) {
    conditions.push('ts.status = ?');
    params.push(status);
  }

  if (conditions.length > 0) {
    query += ' WHERE ' + conditions.join(' AND ');
  }

  query += ' GROUP BY ts.id ORDER BY ts.date DESC, ts.id DESC';

  const sessions = db.prepare(query).all(...params);
  res.json(sessions);
});

