// Update attendance for individual participant or bulk
router.put('/sessions/:id/attendance', authMiddleware, (req, res) => {
  const { updates } = req.body; // Array of { participant_id, attendance }
  if (!Array.isArray(updates) || updates.length === 0) {
    return res.status(400).json({ error: 'Format data update attendance tidak valid.' });
  }

  const db = getDb();
  const updateStmt = db.prepare(`
    UPDATE session_participants
    SET attendance = ?,
        status = CASE WHEN ? = 'Hadir' THEN 'Completed' ELSE 'Registered' END,
        completed_at = CASE WHEN ? = 'Hadir' THEN CURRENT_TIMESTAMP ELSE NULL END
    WHERE session_id = ? AND participant_id = ?
  `);

  const tx = db.transaction((list) => {
    for (const item of list) {
      updateStmt.run(item.attendance, item.attendance, item.attendance, req.params.id, item.participant_id);
    }
  });

  try {
    tx(updates);
    res.json({ success: true, message: 'Data kehadiran berhasil diperbarui.' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Update single quiz score
router.put('/sessions/:id/quiz-score', authMiddleware, (req, res) => {
  const { participant_id, score } = req.body;
  if (participant_id === undefined || score === undefined || score === null) {
    return res.status(400).json({ error: 'Participant ID dan Nilai Score wajib diisi.' });
  }

  const numericScore = parseFloat(score);
  if (isNaN(numericScore) || numericScore < 0 || numericScore > 100) {
    return res.status(400).json({ error: 'Nilai harus berada pada rentang 0 - 100.' });
  }

  const db = getDb();
  const session = db.prepare(`
    SELECT ts.*, t.passing_grade 
    FROM training_sessions ts
    JOIN trainings t ON ts.training_id = t.id
    WHERE ts.id = ?
  `).get(req.params.id);

  if (!session) return res.status(404).json({ error: 'Sesi tidak ditemukan.' });

  const passingGrade = session.passing_grade || 75;
  const result = numericScore >= passingGrade ? 'PASS' : 'FAIL';

  db.prepare(`
    INSERT INTO quiz_scores (session_id, participant_id, score, result)
    VALUES (?, ?, ?, ?)
    ON CONFLICT(session_id, participant_id) DO UPDATE SET
      score = excluded.score,
      result = excluded.result,
      created_at = CURRENT_TIMESTAMP
  `).run(req.params.id, participant_id, numericScore, result);

  // If score is entered, mark attendance as Hadir
  db.prepare(`
    UPDATE session_participants
    SET attendance = 'Hadir', status = 'Completed', completed_at = CURRENT_TIMESTAMP
    WHERE session_id = ? AND participant_id = ?
  `).run(req.params.id, participant_id);

  res.json({ success: true, score: numericScore, result, passing_grade: passingGrade });
});

