// List participants with filters and pagination/search
router.get('/', authMiddleware, (req, res) => {
  const { search, branch, status } = req.query;
  const db = getDb();

  let query = `
    SELECT 
      p.*,
      COUNT(DISTINCT sp.session_id) as total_attended_sessions,
      COUNT(DISTINCT qs.id) as total_quizzes,
      AVG(qs.score) as avg_score
    FROM participants p
    LEFT JOIN session_participants sp ON sp.participant_id = p.id AND sp.attendance = 'Hadir'
    LEFT JOIN quiz_scores qs ON qs.participant_id = p.id
  `;

  const params = [];
  const conditions = [];

  if (search) {
    conditions.push('(p.name LIKE ? OR p.email LIKE ? OR p.nik LIKE ? OR p.phone LIKE ?)');
    const searchTerm = `%${search.trim()}%`;
    params.push(searchTerm, searchTerm, searchTerm, searchTerm);
  }

  if (branch) {
    conditions.push('p.branch = ?');
    params.push(branch);
  }

  if (status) {
    conditions.push('p.status = ?');
    params.push(status);
  }

  if (conditions.length > 0) {
    query += ' WHERE ' + conditions.join(' AND ');
  }

  query += ' GROUP BY p.id ORDER BY p.created_at DESC, p.name ASC';

  const rows = db.prepare(query).all(...params);
  res.json(rows.map(r => ({
    ...r,
    avg_score: r.avg_score ? parseFloat(r.avg_score.toFixed(1)) : null
  })));
});

