// Public Stats Summary
router.get('/stats', (req, res) => {
  try {
    const db = getDb();
    const stats = getDashboardStats();

    // Get active levels and trainings for filters
    const levels = db.prepare('SELECT id, name FROM training_levels WHERE status = "active" ORDER BY order_index ASC').all();
    const trainings = db.prepare('SELECT id, name FROM trainings WHERE status = "active" ORDER BY name ASC').all();
    const branches = db.prepare('SELECT DISTINCT branch FROM participants WHERE branch IS NOT NULL AND branch != "" ORDER BY branch ASC').all().map(b => b.branch);

    res.json({
      summary: stats.summary,
      level_distribution: stats.level_distribution,
      filters: {
        levels,
        trainings,
        branches
      }
