const express = require('express');
const router = express.Router();
const path = require('path');
const { authMiddleware } = require('./auth');
const { 
  createBackup, 
  listBackups, 
  restoreBackup, 
  exportParticipantsCsv, 
  exportRankingsCsv, 
  exportTrainingHistoryCsv 
} = require('../services/backupService');
const { backupsDir } = require('../db/database');

// List Backups
router.get('/backups', authMiddleware, (req, res) => {
  try {
    const backups = listBackups();
    res.json(backups);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Trigger Manual Backup
router.post('/backup', authMiddleware, (req, res) => {
  try {
    const backup = createBackup();
    res.json({ success: true, message: 'Backup database berhasil dibuat.', backup });
  } catch (err) {
    console.error('Backup error:', err);
    res.status(500).json({ error: 'Gagal membuat backup database: ' + err.message });
  }
});

// Download Backup file
router.get('/backups/download/:filename', authMiddleware, (req, res) => {
  const filename = path.basename(req.params.filename);
  const filePath = path.join(backupsDir, filename);
  res.download(filePath);
});

// Restore Database
router.post('/restore', authMiddleware, (req, res) => {
  const { filename } = req.body;
  if (!filename) return res.status(400).json({ error: 'Nama file backup wajib ditentukan.' });

  try {
    const result = restoreBackup(filename);
    res.json(result);
  } catch (err) {
    console.error('Restore error:', err);
    res.status(500).json({ error: 'Gagal merestore database: ' + err.message });
  }
});

// CSV Exports
router.get('/export/participants', authMiddleware, (req, res) => {
  try {
    const csv = exportParticipantsCsv();
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="participants_${Date.now()}.csv"`);
    res.send(csv);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

router.get('/export/rankings', authMiddleware, (req, res) => {
  try {
    const { training_id, level_id, branch } = req.query;
    const csv = exportRankingsCsv({ training_id, level_id, branch });
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="rankings_${Date.now()}.csv"`);
    res.send(csv);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

router.get('/export/training-history', authMiddleware, (req, res) => {
  try {
    const csv = exportTrainingHistoryCsv();
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="training_history_${Date.now()}.csv"`);
    res.send(csv);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

