    }).then(handleResponse),

  getMe: () =>
    fetch(`${API_BASE}/auth/me`, {
      headers: getAuthHeaders()
    }).then(handleResponse),

  changePassword: (current_password, new_password) =>
    fetch(`${API_BASE}/auth/change-password`, {
