import React, { useState } from 'react';
import { X, ClipboardPaste, CheckCircle2, AlertCircle, ArrowRight, Check, AlertTriangle } from 'lucide-react';

export default function CopyPasteModal({
  isOpen,
  onClose,
  title,
  subtitle,
  placeholder,
  exampleFormat,
  onPreview,
  onCommit,
  type = 'participants' // 'participants' | 'quiz' | 'batch_participants'
}) {
  const [step, setStep] = useState(1); // 1: Input text, 2: Preview & Validation
  const [rawText, setRawText] = useState('');
  const [previewData, setPreviewData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [commitSuccess, setCommitSuccess] = useState(null);

  if (!isOpen) return null;

  const handlePreview = async () => {
    if (!rawText.trim()) {
      setError('Harap masukkan data teks copy-paste terlebih dahulu.');
      return;
    }
    setError('');
    setLoading(true);

    try {
      const data = await onPreview(rawText);
      setPreviewData(data);
      setStep(2);
    } catch (err) {
      setError(err.message || 'Gagal memproses data paste.');
    } finally {
      setLoading(false);
    }
  };

  const handleCommit = async () => {
    if (!previewData || previewData.valid_count === 0) {
      setError('Tidak ada data berstatus VALID untuk diimpor.');
      return;
    }

    const validItems = previewData.items.filter(item => item.status === 'VALID');
    setLoading(true);
    setError('');

    try {
      const res = await onCommit(validItems);
      setCommitSuccess(res.message || 'Impor data berhasil diselesaikan.');
      setTimeout(() => {
        handleClose();
      }, 1500);
    } catch (err) {
      setError(err.message || 'Gagal menyimpan data impor.');
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    setStep(1);
    setRawText('');
    setPreviewData(null);
    setError('');
    setCommitSuccess(null);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-full max-w-3xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-150">

        {/* Header */}
        <div className="px-6 py-4 bg-slate-900 text-white flex items-center justify-between">
          <div>
            <h3 className="text-base font-bold flex items-center gap-2">
              <ClipboardPaste className="w-5 h-5 text-blue-400" />
              {title}
            </h3>
            {subtitle && <p className="text-xs text-slate-400 mt-0.5">{subtitle}</p>}
          </div>
          <button 
            onClick={handleClose}
            className="p-1.5 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-white transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Step Indicator */}
        <div className="px-6 py-2.5 bg-slate-100 border-b border-slate-200 flex items-center justify-between text-xs font-semibold">
          <div className="flex items-center gap-2">
            <span className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] ${
              step === 1 ? 'bg-blue-600 text-white font-bold' : 'bg-emerald-600 text-white'
            }`}>
              1
            </span>
            <span className={step === 1 ? 'text-blue-700' : 'text-slate-600'}>Paste Data</span>
            <ArrowRight className="w-3.5 h-3.5 text-slate-400" />
            <span className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] ${
              step === 2 ? 'bg-blue-600 text-white font-bold' : 'bg-slate-300 text-slate-700'
            }`}>
              2
            </span>
            <span className={step === 2 ? 'text-blue-700' : 'text-slate-400'}>Validasi & Preview</span>
          </div>

          {step === 2 && previewData && (
            <div className="flex items-center gap-3">
              <span className="text-emerald-700 bg-emerald-50 border border-emerald-200 px-2 py-0.5 rounded-md font-bold">
                ✓ {previewData.valid_count} VALID
              </span>
              {previewData.invalid_count > 0 && (
                <span className="text-red-700 bg-red-50 border border-red-200 px-2 py-0.5 rounded-md font-bold">
                  ✕ {previewData.invalid_count} INVALID
                </span>
              )}
            </div>
          )}
        </div>

        {/* Modal Body */}
        <div className="p-6 flex-1 overflow-y-auto bg-slate-50/50">
          {error && (
            <div className="mb-4 p-3 rounded-lg bg-red-50 border border-red-200 text-red-700 text-xs flex items-center gap-2">
              <AlertCircle className="w-4 h-4 shrink-0" />
              <span>{error}</span>
            </div>
          )}

          {commitSuccess && (
            <div className="mb-4 p-3 rounded-lg bg-emerald-50 border border-emerald-200 text-emerald-700 text-xs flex items-center gap-2">
              <CheckCircle2 className="w-4 h-4 shrink-0" />
              <span>{commitSuccess}</span>
            </div>
          )}

          {step === 1 && (
            <div className="space-y-4">
              <div className="p-3 bg-blue-50 border border-blue-200 rounded-xl text-xs text-blue-900">
                <div className="font-bold mb-1">Panduan Format Copy-Paste:</div>
                <div className="text-blue-800 font-mono text-[11px] bg-white p-2 rounded border border-blue-100 whitespace-pre-line">
                  {exampleFormat}
                </div>
                <div className="text-blue-700 mt-1.5 text-[11px]">
                  * Data dapat langsung di-copy dari kolom Excel / Google Sheets lalu di-paste di kotak bawah.
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                  Area Paste Clipboard:
                </label>
                <textarea
                  rows={10}
                  value={rawText}
                  onChange={(e) => setRawText(e.target.value)}
                  placeholder={placeholder || 'Tempel teks data di sini...'}
                  className="w-full font-mono text-xs p-3 rounded-xl border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500 bg-white"
                />
              </div>
            </div>
          )}

          {step === 2 && previewData && (
            <div className="space-y-4">
              <div className="text-xs text-slate-600 flex items-center justify-between">
                <span>Total baris terdeteksi: <strong>{previewData.total_rows}</strong> baris</span>
                <span className="text-slate-500 text-[11px]">Hanya baris dengan status <strong>VALID</strong> yang akan disimpan ke database.</span>
              </div>

              <div className="bg-white rounded-xl border border-slate-200 shadow-xs overflow-hidden max-h-96 overflow-y-auto">
                <table className="w-full text-left text-xs">
                  <thead className="bg-slate-100 border-b border-slate-200 text-slate-600 font-semibold sticky top-0 uppercase">
                    <tr>
                      <th className="py-2.5 px-3 w-12 text-center">No</th>
                      <th className="py-2.5 px-3">Email</th>
                      {type === 'participants' && <th className="py-2.5 px-3">Nama Peserta</th>}
                      {type === 'quiz' && <th className="py-2.5 px-3">Nama</th>}
                      {type === 'quiz' && <th className="py-2.5 px-3 text-center">Nilai</th>}
                      {type === 'quiz' && <th className="py-2.5 px-3 text-center">Status Quiz</th>}
                      <th className="py-2.5 px-3 text-center w-24">Status Validasi</th>
                      <th className="py-2.5 px-3">Keterangan / Kesalahan</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {previewData.items.map((row, idx) => {
                      const isValid = row.status === 'VALID';
                      return (
                        <tr key={idx} className={isValid ? 'hover:bg-emerald-50/40' : 'bg-red-50/40 hover:bg-red-50/60'}>
                          <td className="py-2 px-3 text-center text-slate-400 font-mono">{row.line_number}</td>
                          <td className="py-2 px-3 font-medium text-slate-800">{row.email || '-'}</td>

                          {type === 'participants' && (
                            <td className="py-2 px-3 text-slate-700">{row.name || '-'}</td>
                          )}

                          {type === 'quiz' && (
                            <>
                              <td className="py-2 px-3 text-slate-700">{row.participant_name || '-'}</td>
                              <td className="py-2 px-3 text-center font-bold text-slate-800">{row.score !== null ? row.score : '-'}</td>
                              <td className="py-2 px-3 text-center">
                                {row.result ? (
                                  <span className={`px-2 py-0.5 rounded font-bold text-[10px] ${
                                    row.result === 'PASS' ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-800'
                                  }`}>
                                    {row.result}
                                  </span>
                                ) : '-'}
                              </td>
                            </>
                          )}

                          <td className="py-2 px-3 text-center">
                            <span className={`px-2 py-0.5 rounded-full font-bold text-[10px] uppercase ${
                              isValid ? 'bg-emerald-100 text-emerald-800 border border-emerald-300' : 'bg-red-100 text-red-800 border border-red-300'
                            }`}>
                              {row.status}
                            </span>
                          </td>

                          <td className="py-2 px-3 text-[11px]">
                            {isValid ? (
                              <span className="text-emerald-700 flex items-center gap-1 font-medium">
                                <Check className="w-3.5 h-3.5" /> Siap diimpor
                              </span>
                            ) : (
                              <span className="text-red-600 font-semibold flex items-center gap-1">
                                <AlertTriangle className="w-3.5 h-3.5 shrink-0" />
                                {row.errors?.join(', ')}
                              </span>
                            )}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-3.5 bg-slate-100 border-t border-slate-200 flex items-center justify-between">
          {step === 2 ? (
            <button
              onClick={() => setStep(1)}
              disabled={loading}
              className="px-4 py-2 rounded-lg border border-slate-300 text-slate-700 bg-white hover:bg-slate-50 text-xs font-semibold"
            >
              ← Kembali ke Text Paste
            </button>
          ) : (
            <div></div>
          )}

          <div className="flex items-center gap-2">
            <button
              onClick={handleClose}
              className="px-4 py-2 rounded-lg border border-slate-300 text-slate-700 bg-white hover:bg-slate-50 text-xs font-semibold"
            >
              Batal
            </button>

            {step === 1 ? (
              <button
                onClick={handlePreview}
                disabled={loading || !rawText.trim()}
                className="px-5 py-2 rounded-lg bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white text-xs font-bold flex items-center gap-1.5 shadow-xs"
              >
                {loading ? 'Memvalidasi...' : 'Lanjut Preview & Validasi →'}
              </button>
            ) : (
              <button
                onClick={handleCommit}
                disabled={loading || !previewData || previewData.valid_count === 0}
                className="px-5 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 text-white text-xs font-bold flex items-center gap-1.5 shadow-xs"
              >
                {loading ? 'Menyimpan...' : `Impor ${previewData?.valid_count || 0} Record Valid`}
              </button>
            )}
          </div>
        </div>

      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { 
  Users, 
  UserPlus, 
  ClipboardPaste, 
  Download, 
  Search, 
  Filter, 
  MoreVertical, 
  Eye, 
  Edit, 
  Trash2, 
  CheckCircle2, 
  AlertCircle,
  Building,
  Mail,
  Phone,
  CreditCard
} from 'lucide-react';
import { api } from '../services/api';
import AgentProgressModal from '../components/AgentProgressModal';
import CopyPasteModal from '../components/CopyPasteModal';

export default function ParticipantsPage() {
  const [participants, setParticipants] = useState([]);
  const [branches, setBranches] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [branchFilter, setBranchFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');

  // Modals
  const [selectedProgressId, setSelectedProgressId] = useState(null);
  const [isCopyPasteOpen, setIsCopyPasteOpen] = useState(false);
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [editingParticipant, setEditingParticipant] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    nik: '',
    phone: '',
    branch: '',
    status: 'active'
  });
  const [formError, setFormError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    loadBranches();
    loadParticipants();
  }, [search, branchFilter, statusFilter]);

  const loadBranches = async () => {
    try {
      const list = await api.getBranches();
      setBranches(list);
    } catch (e) {
      console.error(e);
    }
  };

  const loadParticipants = async () => {
    setLoading(true);
    try {
      const data = await api.getParticipants({
        search,
        branch: branchFilter,
        status: statusFilter
      });
      setParticipants(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleOpenCreate = () => {
    setEditingParticipant(null);
    setFormData({
      name: '',
      email: '',
      nik: '',
      phone: '',
      branch: '',
      status: 'active'
    });
    setFormError('');
    setIsFormModalOpen(true);
  };

  const handleOpenEdit = (p) => {
    setEditingParticipant(p);
    setFormData({
      name: p.name,
      email: p.email,
      nik: p.nik || '',
      phone: p.phone || '',
      branch: p.branch || '',
      status: p.status || 'active'
    });
    setFormError('');
    setIsFormModalOpen(true);
  };

  const handleSubmitForm = async (e) => {
    e.preventDefault();
    if (!formData.name.trim() || !formData.email.trim()) {
      setFormError('Nama dan Email wajib diisi.');
      return;
    }

    setIsSubmitting(true);
    setFormError('');

    try {
      if (editingParticipant) {
        await api.updateParticipant(editingParticipant.id, formData);
      } else {
        await api.createParticipant(formData);
      }
      setIsFormModalOpen(false);
      loadParticipants();
      loadBranches();
    } catch (err) {
      setFormError(err.message || 'Gagal menyimpan data peserta.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (p) => {
    if (window.confirm(`Yakin ingin menghapus peserta ${p.name} (${p.email})? Riwayat kehadiran dan nilai quiz terkait juga akan dihapus.`)) {
      try {
        await api.deleteParticipant(p.id);
        loadParticipants();
      } catch (err) {
        alert(err.message || 'Gagal menghapus peserta.');
      }
    }
  };

  const handleExportCsv = () => {
    window.location.href = api.getExportUrl('participants');
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-200">

      {/* Top Bar with Title and Actions */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-5 rounded-2xl border border-slate-200 shadow-xs">
        <div>
          <h2 className="text-xl font-bold text-slate-800">Manajemen Peserta / Agen</h2>
          <p className="text-xs text-slate-500 mt-0.5">
            Kelola data agen, pantau keikutsertaan pelatihan, dan cek progress kelulusan level kurikulum.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2.5">
          <button
            onClick={handleExportCsv}
            className="px-3.5 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-semibold flex items-center gap-1.5 transition-all"
          >
            <Download className="w-4 h-4" />
            <span>Export CSV</span>
          </button>

          <button
            onClick={() => setIsCopyPasteOpen(true)}
            className="px-3.5 py-2 rounded-xl bg-indigo-50 hover:bg-indigo-100 text-indigo-700 border border-indigo-200 text-xs font-semibold flex items-center gap-1.5 transition-all"
          >
            <ClipboardPaste className="w-4 h-4" />
            <span>Copy-Paste Import</span>
          </button>

          <button
            onClick={handleOpenCreate}
            className="px-4 py-2 rounded-xl bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold flex items-center gap-1.5 transition-all shadow-md shadow-blue-600/20"
          >
            <UserPlus className="w-4 h-4" />
            <span>Tambah Peserta</span>
          </button>
        </div>
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-3 flex-1 min-w-[300px]">
          <div className="relative flex-1 max-w-md">
            <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              placeholder="Cari nama, email, NIK, nomor HP..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-9 pr-3 py-1.5 text-xs bg-slate-50 border border-slate-200 rounded-lg focus:outline-hidden focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div className="flex items-center gap-2">
            <Filter className="w-3.5 h-3.5 text-slate-400" />
            <select
              value={branchFilter}
              onChange={(e) => setBranchFilter(e.target.value)}
              className="text-xs py-1.5 px-2.5 bg-slate-50 border border-slate-200 rounded-lg text-slate-700"
            >
              <option value="">Semua Cabang</option>
              {branches.map(b => (
                <option key={b} value={b}>{b}</option>
              ))}
            </select>

            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="text-xs py-1.5 px-2.5 bg-slate-50 border border-slate-200 rounded-lg text-slate-700"
            >
              <option value="">Semua Status</option>
              <option value="active">Active</option>
              <option value="inactive">Inactive</option>
            </select>
          </div>
        </div>

        <div className="text-xs text-slate-500 font-medium">
          Ditemukan <strong>{participants.length}</strong> peserta
        </div>
      </div>

      {/* Participants Table */}
      <div className="bg-white rounded-2xl border border-slate-200 shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="bg-slate-50 border-b border-slate-200 text-slate-600 font-semibold uppercase">
              <tr>
                <th className="py-3 px-4">Nama & Email</th>
                <th className="py-3 px-4">NIK & No. HP</th>
                <th className="py-3 px-4">Cabang</th>
                <th className="py-3 px-4 text-center">Kehadiran</th>
                <th className="py-3 px-4 text-center">Quiz</th>
                <th className="py-3 px-4 text-center">Rata-Rata</th>
                <th className="py-3 px-4 text-center">Status</th>
                <th className="py-3 px-4 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan="8" className="py-16 text-center text-slate-400">
                    <div className="w-6 h-6 border-2 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-2"></div>
                    Memuat data peserta...
                  </td>
                </tr>
              ) : participants.length === 0 ? (
                <tr>
                  <td colSpan="8" className="py-16 text-center text-slate-400">
                    Tidak ada data peserta ditemukan.
                  </td>
                </tr>
              ) : (
                participants.map(p => (
                  <tr key={p.id} className="hover:bg-slate-50/80 transition-colors">
                    <td className="py-3 px-4">
                      <div className="font-bold text-slate-800 text-sm">{p.name}</div>
                      <div className="text-slate-500 flex items-center gap-1 mt-0.5">
                        <Mail className="w-3 h-3 text-slate-400" />
                        <span>{p.email}</span>
                      </div>
                    </td>
                    <td className="py-3 px-4">
                      <div className="text-slate-700 font-mono">{p.nik || '-'}</div>
                      <div className="text-slate-500">{p.phone || '-'}</div>
                    </td>
                    <td className="py-3 px-4">
                      {p.branch ? (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-slate-100 text-slate-700 font-medium">
                          <Building className="w-3 h-3 text-slate-400" /> {p.branch}
                        </span>
                      ) : (
                        <span className="text-slate-400">-</span>
                      )}
                    </td>
                    <td className="py-3 px-4 text-center">
                      <span className="font-semibold text-slate-700">{p.total_attended_sessions} Sesi</span>
                    </td>
                    <td className="py-3 px-4 text-center">
                      <span className="font-semibold text-slate-700">{p.total_quizzes} Quiz</span>
                    </td>
                    <td className="py-3 px-4 text-center">
                      {p.avg_score !== null ? (
                        <span className="font-bold text-blue-600 text-sm">{p.avg_score}</span>
                      ) : (
                        <span className="text-slate-400">-</span>
                      )}
                    </td>
                    <td className="py-3 px-4 text-center">
                      <span className={`px-2.5 py-0.5 rounded-full font-bold uppercase text-[10px] ${
                        p.status === 'active' 
                          ? 'bg-emerald-100 text-emerald-800 border border-emerald-200' 
                          : 'bg-slate-100 text-slate-600 border border-slate-300'
                      }`}>
                        {p.status}
                      </span>
                    </td>
                    <td className="py-3 px-4 text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <button
                          onClick={() => setSelectedProgressId(p.id)}
                          title="Lihat Progress & Riwayat Agen"
                          className="px-2.5 py-1.5 rounded-lg bg-blue-50 hover:bg-blue-100 text-blue-700 font-semibold text-xs flex items-center gap-1 transition-colors"
                        >
                          <Eye className="w-3.5 h-3.5" />
                          <span>Progress</span>
                        </button>
                        <button
                          onClick={() => handleOpenEdit(p)}
                          title="Edit Peserta"
                          className="p-1.5 rounded-lg hover:bg-slate-100 text-slate-600 transition-colors"
                        >
                          <Edit className="w-3.5 h-3.5" />
                        </button>
                        <button
                          onClick={() => handleDelete(p)}
                          title="Hapus Peserta"
                          className="p-1.5 rounded-lg hover:bg-red-50 text-red-600 transition-colors"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Progress & History Drill-down Modal (PRD Section 16 & 17) */}
      <AgentProgressModal
        participantId={selectedProgressId}
        onClose={() => setSelectedProgressId(null)}
      />

      {/* Copy Paste Import Modal (PRD Section 19.1 & 20) */}
      <CopyPasteModal
        isOpen={isCopyPasteOpen}
        onClose={() => {
          setIsCopyPasteOpen(false);
          loadParticipants();
          loadBranches();
        }}
        type="participants"
        title="Copy-Paste Import Data Peserta"
        subtitle="Tempel data peserta langsung dari file Excel atau CSV."
        exampleFormat={`budi@email.com\tBudi Santoso\t3171012345670001\t081234567890\tJakarta Pusat\nsiti@email.com\tSiti Rahma\t3273012345670002\t081234567891\tBandung\nandi@email.com`}
        placeholder="budi@email.com\tBudi Santoso\nsiti@email.com\tSiti Rahma"
        onPreview={(text) => api.previewImportParticipants(text)}
        onCommit={(items) => api.commitImportParticipants(items)}
      />

      {/* Add / Edit Participant Modal */}
      {isFormModalOpen && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-full max-w-md overflow-hidden animate-in fade-in zoom-in-95 duration-150">
            <div className="px-6 py-4 bg-slate-900 text-white flex items-center justify-between">
              <h3 className="font-bold text-base">
                {editingParticipant ? 'Edit Data Peserta' : 'Tambah Peserta Baru'}
              </h3>
              <button 
                onClick={() => setIsFormModalOpen(false)}
                className="p-1 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-white"
              >
                ✕
              </button>
            </div>

            <form onSubmit={handleSubmitForm} className="p-6 space-y-4">
              {formError && (
                <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-xs text-red-700 flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 shrink-0" />
                  <span>{formError}</span>
                </div>
              )}

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Nama Lengkap <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  required
                  placeholder="Contoh: Budi Santoso"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Email (Unique Identifier) <span className="text-red-500">*</span>
                </label>
                <input
                  type="email"
                  required
                  placeholder="budi.santoso@email.com"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                    NIK (Opsional)
                  </label>
                  <input
                    type="text"
                    placeholder="317101..."
                    value={formData.nik}
                    onChange={(e) => setFormData({ ...formData, nik: e.target.value })}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                    No. HP (Opsional)
                  </label>
                  <input
                    type="text"
                    placeholder="0812..."
                    value={formData.phone}
                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                    Cabang (Opsional)
                  </label>
                  <input
                    type="text"
                    placeholder="Contoh: Jakarta Pusat"
                    value={formData.branch}
                    onChange={(e) => setFormData({ ...formData, branch: e.target.value })}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                    Status
                  </label>
                  <select
                    value={formData.status}
                    onChange={(e) => setFormData({ ...formData, status: e.target.value })}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="active">Active</option>
                    <option value="inactive">Inactive</option>
                  </select>
                </div>
              </div>

              <div className="pt-3 flex justify-end gap-2 border-t border-slate-100">
                <button
                  type="button"
                  onClick={() => setIsFormModalOpen(false)}
                  className="px-4 py-2 rounded-lg border border-slate-300 text-slate-700 text-xs font-semibold hover:bg-slate-50"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className="px-5 py-2 rounded-lg bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold disabled:opacity-50"
                >
                  {isSubmitting ? 'Menyimpan...' : 'Simpan Peserta'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { 
  BookOpen, 
  Layers, 
  Plus, 
  Edit, 
  Trash2, 
  CheckCircle2, 
  AlertCircle, 
  HelpCircle,
  Sparkles,
  ArrowUpDown
} from 'lucide-react';
import { api } from '../services/api';

export default function CurriculumPage() {
  const [levels, setLevels] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [loading, setLoading] = useState(true);

  // Level Modal
  const [isLevelModalOpen, setIsLevelModalOpen] = useState(false);
  const [editingLevel, setEditingLevel] = useState(null);
  const [levelForm, setLevelForm] = useState({ name: '', order_index: 1, status: 'active' });

  // Subject Modal
  const [isSubjectModalOpen, setIsSubjectModalOpen] = useState(false);
  const [editingSubject, setEditingSubject] = useState(null);
  const [subjectForm, setSubjectForm] = useState({ level_id: '', name: '', is_required: 1, status: 'active' });

  const [modalError, setModalError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [levelsData, subjectsData] = await Promise.all([
        api.getLevels(),
        api.getSubjects()
      ]);
      setLevels(levelsData);
      setSubjects(subjectsData);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  // Level handlers
  const handleOpenCreateLevel = () => {
    setEditingLevel(null);
    setLevelForm({
      name: '',
      order_index: (levels.length > 0 ? Math.max(...levels.map(l => l.order_index)) : 0) + 1,
      status: 'active'
    });
    setModalError('');
    setIsLevelModalOpen(true);
  };

  const handleOpenEditLevel = (lvl) => {
    setEditingLevel(lvl);
    setLevelForm({
      name: lvl.name,
      order_index: lvl.order_index,
      status: lvl.status
    });
    setModalError('');
    setIsLevelModalOpen(true);
  };

  const handleSubmitLevel = async (e) => {
    e.preventDefault();
    if (!levelForm.name.trim()) {
      setModalError('Nama level wajib diisi.');
      return;
    }
    setIsSubmitting(true);
    setModalError('');
    try {
      if (editingLevel) {
        await api.updateLevel(editingLevel.id, levelForm);
      } else {
        await api.createLevel(levelForm);
      }
      setIsLevelModalOpen(false);
      loadData();
    } catch (err) {
      setModalError(err.message || 'Gagal menyimpan level.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteLevel = async (lvl) => {
    if (window.confirm(`Yakin ingin menghapus level "${lvl.name}"?`)) {
      try {
        await api.deleteLevel(lvl.id);
        loadData();
      } catch (err) {
        alert(err.message || 'Gagal menghapus level.');
      }
