  // Subject handlers
  const handleOpenCreateSubject = (defaultLevelId = null) => {
    setEditingSubject(null);
    setSubjectForm({
      level_id: defaultLevelId || (levels[0]?.id || ''),
      name: '',
      is_required: 1,
      status: 'active'
    });
    setModalError('');
    setIsSubjectModalOpen(true);
