    setEditingSubject(sub);
    setSubjectForm({
      level_id: sub.level_id,
      name: sub.name,
      is_required: sub.is_required ? 1 : 0,
      status: sub.status
    });
    setModalError('');
    setIsSubjectModalOpen(true);
