import React, { useState, useEffect } from 'react';
import { 
  GraduationCap, 
  Plus, 
  Edit, 
  Trash2, 
  CheckCircle2, 
  AlertCircle, 
  Award, 
  Filter, 
  Search,
  BookOpen
} from 'lucide-react';
import { api } from '../services/api';

export default function TrainingsPage() {
  const [trainings, setTrainings] = useState([]);
  const [levels, setLevels] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [loading, setLoading] = useState(true);

  const [levelFilter, setLevelFilter] = useState('');
  const [subjectFilter, setSubjectFilter] = useState('');
  const [search, setSearch] = useState('');

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTraining, setEditingTraining] = useState(null);
  const [formData, setFormData] = useState({
    code: '',
    name: '',
    subject_id: '',
    has_quiz: 1,
    passing_grade: 75,
    status: 'active'
  });
  const [formError, setFormError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    loadMetadata();
    loadTrainings();
  }, [levelFilter, subjectFilter]);

  const loadMetadata = async () => {
    try {
      const [levelsData, subjectsData] = await Promise.all([
        api.getLevels(),
        api.getSubjects()
      ]);
      setLevels(levelsData);
      setSubjects(subjectsData);
    } catch (e) {
      console.error(e);
    }
  };

  const loadTrainings = async () => {
    setLoading(true);
    try {
      const data = await api.getTrainings({
        level_id: levelFilter,
        subject_id: subjectFilter
      });
      setTrainings(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleOpenCreate = () => {
    setEditingTraining(null);
    setFormData({
      code: '',
      name: '',
      subject_id: subjects[0]?.id || '',
      has_quiz: 1,
      passing_grade: 75,
      status: 'active'
    });
    setFormError('');
    setIsModalOpen(true);
  };

  const handleOpenEdit = (t) => {
    setEditingTraining(t);
    setFormData({
      code: t.code || '',
      name: t.name,
      subject_id: t.subject_id,
      has_quiz: t.has_quiz ? 1 : 0,
      passing_grade: t.passing_grade || 75,
      status: t.status || 'active'
    });
    setFormError('');
    setIsModalOpen(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.name.trim() || !formData.subject_id) {
      setFormError('Nama Training dan Subject wajib diisi.');
      return;
    }

    setIsSubmitting(true);
    setFormError('');

    try {
      if (editingTraining) {
        await api.updateTraining(editingTraining.id, formData);
      } else {
        await api.createTraining(formData);
      }
      setIsModalOpen(false);
      loadTrainings();
    } catch (err) {
      setFormError(err.message || 'Gagal menyimpan training master.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (t) => {
    if (window.confirm(`Yakin ingin menghapus Master Training "${t.name}"?`)) {
      try {
        await api.deleteTraining(t.id);
        loadTrainings();
      } catch (err) {
        alert(err.message || 'Gagal menghapus training.');
      }
    }
  };

  const filteredTrainings = trainings.filter(t => {
    if (!search.trim()) return true;
    const term = search.toLowerCase();
    return (
      t.name.toLowerCase().includes(term) ||
      (t.code && t.code.toLowerCase().includes(term)) ||
      t.subject_name.toLowerCase().includes(term)
    );
  });

  return (
    <div className="space-y-6 animate-in fade-in duration-200">

      {/* Header Banner */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-5 rounded-2xl border border-slate-200 shadow-xs">
        <div>
          <h2 className="text-xl font-bold text-slate-800">Master Training</h2>
          <p className="text-xs text-slate-500 mt-0.5">
            Definisi katalog materi dan silabus training yang dikaitkan ke Subject dan Level kompetensi.
          </p>
        </div>

        <button
          onClick={handleOpenCreate}
          className="px-4 py-2 rounded-xl bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold flex items-center gap-1.5 transition-all shadow-md shadow-blue-600/20"
        >
          <Plus className="w-4 h-4" />
          <span>Tambah Training Master</span>
        </button>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-3 flex-1 min-w-[300px]">
          <div className="relative flex-1 max-w-sm">
            <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              placeholder="Cari kode atau nama training..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-9 pr-3 py-1.5 text-xs bg-slate-50 border border-slate-200 rounded-lg focus:outline-hidden focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div className="flex items-center gap-2">
            <Filter className="w-3.5 h-3.5 text-slate-400" />
            <select
              value={levelFilter}
              onChange={(e) => setLevelFilter(e.target.value)}
              className="text-xs py-1.5 px-2.5 bg-slate-50 border border-slate-200 rounded-lg text-slate-700"
            >
              <option value="">Semua Level</option>
              {levels.map(l => (
                <option key={l.id} value={l.id}>{l.name}</option>
              ))}
            </select>

            <select
              value={subjectFilter}
              onChange={(e) => setSubjectFilter(e.target.value)}
              className="text-xs py-1.5 px-2.5 bg-slate-50 border border-slate-200 rounded-lg text-slate-700 max-w-[200px]"
            >
              <option value="">Semua Subject</option>
              {subjects.map(s => (
                <option key={s.id} value={s.id}>{s.name}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="text-xs text-slate-500 font-medium">
          Ditemukan <strong>{filteredTrainings.length}</strong> master training
        </div>
      </div>

      {/* Trainings Table */}
      <div className="bg-white rounded-2xl border border-slate-200 shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="bg-slate-50 border-b border-slate-200 text-slate-600 font-semibold uppercase">
              <tr>
                <th className="py-3 px-4">Kode & Nama Training</th>
                <th className="py-3 px-4">Subject & Level</th>
                <th className="py-3 px-4 text-center">Quiz & Passing Grade</th>
                <th className="py-3 px-4 text-center">Riwayat Batch</th>
                <th className="py-3 px-4 text-center">Status</th>
                <th className="py-3 px-4 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan="6" className="py-16 text-center text-slate-400">
                    <div className="w-6 h-6 border-2 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-2"></div>
                    Memuat data master training...
                  </td>
                </tr>
              ) : filteredTrainings.length === 0 ? (
                <tr>
                  <td colSpan="6" className="py-16 text-center text-slate-400">
                    Tidak ada master training ditemukan.
                  </td>
                </tr>
              ) : (
                filteredTrainings.map(t => (
                  <tr key={t.id} className="hover:bg-slate-50/80 transition-colors">
                    <td className="py-3 px-4">
                      {t.code && (
                        <div className="text-[11px] font-mono font-bold text-blue-600">{t.code}</div>
                      )}
                      <div className="font-bold text-slate-800 text-sm">{t.name}</div>
                    </td>
                    <td className="py-3 px-4">
                      <div className="font-medium text-slate-800">{t.subject_name}</div>
                      <span className="inline-block mt-0.5 text-[10px] font-bold px-1.5 py-0.2 rounded bg-blue-50 text-blue-700 border border-blue-100">
                        {t.level_name}
                      </span>
                    </td>
                    <td className="py-3 px-4 text-center">
                      {t.has_quiz ? (
                        <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-purple-50 text-purple-700 border border-purple-200 font-bold text-xs">
                          <Award className="w-3.5 h-3.5" />
                          <span>Ada Quiz (Min: {t.passing_grade})</span>
                        </div>
                      ) : (
                        <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full bg-slate-100 text-slate-600 text-xs font-medium">
                          Tanpa Quiz (Hadir Only)
                        </span>
                      )}
                    </td>
                    <td className="py-3 px-4 text-center">
                      <span className="font-semibold text-slate-700">{t.total_sessions || 0} Batch</span>
                    </td>
                    <td className="py-3 px-4 text-center">
                      <span className={`px-2.5 py-0.5 rounded-full font-bold uppercase text-[10px] ${
                        t.status === 'active' 
                          ? 'bg-emerald-100 text-emerald-800 border border-emerald-200' 
                          : 'bg-slate-100 text-slate-600 border border-slate-300'
                      }`}>
                        {t.status}
                      </span>
                    </td>
                    <td className="py-3 px-4 text-right">
                      <div className="flex items-center justify-end gap-1">
                        <button
                          onClick={() => handleOpenEdit(t)}
                          className="p-1.5 rounded-lg hover:bg-slate-100 text-slate-600"
                          title="Edit Master Training"
                        >
                          <Edit className="w-3.5 h-3.5" />
                        </button>
                        <button
                          onClick={() => handleDelete(t)}
                          className="p-1.5 rounded-lg hover:bg-red-50 text-red-600"
                          title="Hapus Master Training"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add / Edit Training Master Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-full max-w-md overflow-hidden animate-in fade-in zoom-in-95 duration-150">
            <div className="px-6 py-4 bg-slate-900 text-white flex items-center justify-between">
              <h3 className="font-bold text-base">
                {editingTraining ? 'Edit Training Master' : 'Tambah Training Master Baru'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="p-1 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-white">✕</button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              {formError && (
                <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-xs text-red-700 flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 shrink-0" />
                  <span>{formError}</span>
                </div>
              )}

              <div className="grid grid-cols-3 gap-3">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">Kode Training</label>
                  <input
                    type="text"
                    placeholder="TRN-01"
                    value={formData.code}
                    onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 font-mono focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div className="col-span-2">
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                    Nama Training <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    required
                    placeholder="Contoh: Basic Insurance Foundation"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Subject / Materi Kurikulum <span className="text-red-500">*</span>
                </label>
                <select
                  required
                  value={formData.subject_id}
                  onChange={(e) => setFormData({ ...formData, subject_id: e.target.value })}
                  className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                >
                  <option value="">Pilih Subject...</option>
                  {subjects.map(s => (
                    <option key={s.id} value={s.id}>[{s.level_name}] {s.name}</option>
                  ))}
                </select>
                <p className="text-[11px] text-slate-400 mt-1">Level training akan otomatis mengikuti level dari subject terpilih.</p>
              </div>

              <div className="grid grid-cols-2 gap-3 p-3 bg-slate-50 rounded-xl border border-slate-200">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">Memiliki Quiz?</label>
                  <select
                    value={formData.has_quiz}
                    onChange={(e) => setFormData({ ...formData, has_quiz: parseInt(e.target.value) })}
                    className="w-full text-xs p-2 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500 font-semibold"
                  >
                    <option value={1}>Ya, Ada Quiz</option>
                    <option value={0}>Tidak (Hanya Kehadiran)</option>
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">Passing Grade</label>
                  <input
                    type="number"
                    min="0"
                    max="100"
                    disabled={formData.has_quiz === 0}
                    value={formData.passing_grade}
                    onChange={(e) => setFormData({ ...formData, passing_grade: parseInt(e.target.value) || 0 })}
                    className="w-full text-xs p-2 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500 font-bold disabled:bg-slate-200"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">Status</label>
                <select
                  value={formData.status}
                  onChange={(e) => setFormData({ ...formData, status: e.target.value })}
                  className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                >
                  <option value="active">Active</option>
                  <option value="inactive">Inactive</option>
                </select>
              </div>

              <div className="pt-3 flex justify-end gap-2 border-t border-slate-100">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 rounded-lg border border-slate-300 text-slate-700 text-xs font-semibold hover:bg-slate-50"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className="px-5 py-2 rounded-lg bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold disabled:opacity-50"
                >
                  {isSubmitting ? 'Menyimpan...' : 'Simpan Master Training'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { 
  CalendarDays, 
  Plus, 
  Edit, 
  Trash2, 
  Users, 
  Award, 
  CheckCircle2, 
  AlertCircle, 
  ClipboardPaste, 
  Check, 
  ArrowLeft,
  Search,
  Filter,
  UserPlus,
  Save,
  MapPin,
  UserCheck
} from 'lucide-react';
import { api } from '../services/api';
import CopyPasteModal from '../components/CopyPasteModal';

export default function SessionsPage() {
  const [sessions, setSessions] = useState([]);
  const [trainings, setTrainings] = useState([]);
  const [allParticipants, setAllParticipants] = useState([]);
  const [loading, setLoading] = useState(true);

  // Active Session Detail Mode
  const [activeSession, setActiveSession] = useState(null);
  const [sessionParticipants, setSessionParticipants] = useState([]);
  const [loadingParticipants, setLoadingParticipants] = useState(false);

  // Filter
  const [statusFilter, setStatusFilter] = useState('');
  const [trainingFilter, setTrainingFilter] = useState('');

  // Modals
  const [isSessionModalOpen, setIsSessionModalOpen] = useState(false);
  const [editingSession, setEditingSession] = useState(null);
  const [sessionForm, setSessionForm] = useState({
    training_id: '',
    batch_name: '',
    date: new Date().toISOString().split('T')[0],
    trainer: '',
    location: '',
    status: 'Scheduled',
    notes: ''
  });

  // Batch Modals
  const [isAddParticipantModalOpen, setIsAddParticipantModalOpen] = useState(false);
  const [selectedParticipantToAdd, setSelectedParticipantToAdd] = useState('');
  const [isBatchPasteParticipantsOpen, setIsBatchPasteParticipantsOpen] = useState(false);
  const [isImportQuizOpen, setIsImportQuizOpen] = useState(false);

  // Local Edits State for Quick Attendance / Scoring in Active Session
  const [pendingScores, setPendingScores] = useState({});
  const [pendingAttendance, setPendingAttendance] = useState({});
  const [saveSuccessMsg, setSaveSuccessMsg] = useState('');
  const [modalError, setModalError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    loadMetadata();
    loadSessions();
  }, [statusFilter, trainingFilter]);

  const loadMetadata = async () => {
    try {
      const [trnData, partData] = await Promise.all([
        api.getTrainings(),
        api.getParticipants({ status: 'active' })
      ]);
      setTrainings(trnData);
      setAllParticipants(partData);
    } catch (e) {
      console.error(e);
    }
  };

  const loadSessions = async () => {
    setLoading(true);
    try {
      const data = await api.getSessions({
        status: statusFilter,
        training_id: trainingFilter
      });
      setSessions(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const loadSessionParticipants = async (sessionId) => {
    setLoadingParticipants(true);
    try {
      const list = await api.getSessionParticipants(sessionId);
      setSessionParticipants(list);
      // Reset pending edits
      const scoresMap = {};
      const attendMap = {};
      list.forEach(p => {
        scoresMap[p.participant_id] = p.quiz_score !== null ? p.quiz_score : '';
        attendMap[p.participant_id] = p.attendance;
      });
      setPendingScores(scoresMap);
      setPendingAttendance(attendMap);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingParticipants(false);
    }
  };

  const handleOpenSessionDetail = async (sess) => {
    setActiveSession(sess);
    await loadSessionParticipants(sess.id);
  };

  const handleBackToList = () => {
    setActiveSession(null);
    setSaveSuccessMsg('');
    loadSessions();
  };

  // Session Form
  const handleOpenCreateSession = () => {
    setEditingSession(null);
    setSessionForm({
      training_id: trainings[0]?.id || '',
      batch_name: '',
      date: new Date().toISOString().split('T')[0],
      trainer: '',
      location: '',
      status: 'Scheduled',
      notes: ''
    });
    setModalError('');
    setIsSessionModalOpen(true);
  };

  const handleOpenEditSession = (s, e) => {
    e?.stopPropagation();
    setEditingSession(s);
    setSessionForm({
      training_id: s.training_id,
      batch_name: s.batch_name,
      date: s.date,
      trainer: s.trainer || '',
      location: s.location || '',
      status: s.status,
      notes: s.notes || ''
    });
    setModalError('');
    setIsSessionModalOpen(true);
  };

  const handleSubmitSession = async (e) => {
    e.preventDefault();
    if (!sessionForm.training_id || !sessionForm.batch_name.trim() || !sessionForm.date) {
      setModalError('Training, Nama Batch, dan Tanggal wajib diisi.');
      return;
    }

    setIsSubmitting(true);
    setModalError('');
    try {
      if (editingSession) {
        await api.updateSession(editingSession.id, sessionForm);
      } else {
        await api.createSession(sessionForm);
      }
      setIsSessionModalOpen(false);
      loadSessions();
    } catch (err) {
      setModalError(err.message || 'Gagal menyimpan batch pelaksanaan.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteSession = async (s, e) => {
    e?.stopPropagation();
    if (window.confirm(`Yakin ingin menghapus pelaksanaan batch "${s.batch_name}"?`)) {
      try {
        await api.deleteSession(s.id);
        if (activeSession?.id === s.id) {
          setActiveSession(null);
        }
        loadSessions();
      } catch (err) {
        alert(err.message || 'Gagal menghapus batch.');
      }
    }
  };

  // Active Batch: Attendance & Scoring actions
  const handleAttendanceChange = (participantId, newStatus) => {
    setPendingAttendance(prev => ({
      ...prev,
      [participantId]: newStatus
    }));
  };

  const handleScoreChange = (participantId, newScore) => {
    setPendingScores(prev => ({
      ...prev,
      [participantId]: newScore
    }));
    // If score entered and > 0, auto-suggest Hadir
    if (newScore !== '' && parseFloat(newScore) >= 0) {
      setPendingAttendance(prev => ({
        ...prev,
        [participantId]: 'Hadir'
      }));
    }
  };

  const handleSaveBatchChanges = async () => {
    if (!activeSession) return;
    setIsSubmitting(true);
    setSaveSuccessMsg('');

    try {
      // 1. Bulk update attendance
      const attendanceUpdates = Object.keys(pendingAttendance).map(pid => ({
        participant_id: parseInt(pid),
        attendance: pendingAttendance[pid]
      }));

      if (attendanceUpdates.length > 0) {
        await api.updateSessionAttendance(activeSession.id, attendanceUpdates);
      }

      // 2. Update quiz scores
      for (const pid of Object.keys(pendingScores)) {
        const val = pendingScores[pid];
        if (val !== '' && val !== null && !isNaN(parseFloat(val))) {
          await api.updateSessionQuizScore(activeSession.id, parseInt(pid), parseFloat(val));
        }
      }

      setSaveSuccessMsg('Seluruh perubahan kehadiran & nilai berhasil disimpan dan kelulusan otomatis terupdate!');
      await loadSessionParticipants(activeSession.id);
      setTimeout(() => setSaveSuccessMsg(''), 4000);
    } catch (err) {
      alert(err.message || 'Gagal menyimpan perubahan batch.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleAddSingleParticipant = async (e) => {
    e.preventDefault();
    if (!selectedParticipantToAdd) return;

    try {
      await api.addSessionParticipant(activeSession.id, selectedParticipantToAdd);
      setIsAddParticipantModalOpen(false);
      setSelectedParticipantToAdd('');
      await loadSessionParticipants(activeSession.id);
    } catch (err) {
      alert(err.message || 'Gagal menambahkan peserta.');
    }
  };

  const handleRemoveParticipant = async (pid, name) => {
    if (window.confirm(`Hapus peserta ${name} dari batch ini?`)) {
      try {
        await api.removeSessionParticipant(activeSession.id, pid);
        await loadSessionParticipants(activeSession.id);
      } catch (err) {
        alert(err.message || 'Gagal menghapus peserta.');
      }
    }
  };

  // Render Batch Detail View
  if (activeSession) {
    const passingGrade = activeSession.passing_grade || 75;

    return (
      <div className="space-y-6 animate-in fade-in duration-200">

        {/* Detail Top Header */}
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-xs flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <button
              onClick={handleBackToList}
              className="p-2 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 transition-colors"
              title="Kembali ke Daftar Batch"
            >
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div>
              <div className="flex items-center gap-2">
                <span className="text-xs px-2 py-0.5 rounded-full font-bold uppercase bg-blue-100 text-blue-800 border border-blue-200">
                  {activeSession.level_name} • {activeSession.subject_name}
                </span>
                <span className={`text-xs px-2.5 py-0.5 rounded-full font-bold uppercase ${
                  activeSession.status === 'Completed' ? 'bg-emerald-100 text-emerald-800' :
                  activeSession.status === 'Ongoing' ? 'bg-amber-100 text-amber-800' : 'bg-slate-100 text-slate-600'
                }`}>
                  {activeSession.status}
                </span>
              </div>
              <h2 className="text-xl font-bold text-slate-900 mt-1">
                {activeSession.training_name} — <span className="text-blue-600">{activeSession.batch_name}</span>
              </h2>
              <div className="flex flex-wrap items-center gap-4 text-xs text-slate-500 mt-1">
                <span>Tanggal: <strong>{activeSession.date}</strong></span>
                {activeSession.trainer && <span>Trainer: <strong>{activeSession.trainer}</strong></span>}
                {activeSession.location && <span>Lokasi: <strong>{activeSession.location}</strong></span>}
                {activeSession.has_quiz ? (
                  <span className="text-purple-700 font-bold bg-purple-50 px-2 py-0.5 rounded">
                    Passing Grade: {passingGrade}
                  </span>
                ) : (
                  <span className="text-slate-600 bg-slate-100 px-2 py-0.5 rounded">Tanpa Quiz</span>
                )}
              </div>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={() => setIsBatchPasteParticipantsOpen(true)}
              className="px-3.5 py-2 rounded-xl bg-indigo-50 hover:bg-indigo-100 text-indigo-700 border border-indigo-200 text-xs font-semibold flex items-center gap-1.5 transition-all"
            >
              <ClipboardPaste className="w-4 h-4" />
              <span>Paste Peserta</span>
            </button>

            {activeSession.has_quiz === 1 && (
              <button
                onClick={() => setIsImportQuizOpen(true)}
                className="px-3.5 py-2 rounded-xl bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200 text-xs font-bold flex items-center gap-1.5 transition-all"
              >
                <Award className="w-4 h-4" />
                <span>Import Nilai (Copy-Paste)</span>
              </button>
            )}

            <button
              onClick={() => setIsAddParticipantModalOpen(true)}
              className="px-3.5 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-800 text-xs font-semibold flex items-center gap-1.5"
            >
              <UserPlus className="w-4 h-4" />
              <span>Tambah 1 Peserta</span>
            </button>

            <button
              onClick={handleSaveBatchChanges}
              disabled={isSubmitting}
              className="px-4 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold flex items-center gap-1.5 shadow-md shadow-emerald-600/20 disabled:opacity-50"
            >
              <Save className="w-4 h-4" />
              <span>{isSubmitting ? 'Menyimpan...' : 'Simpan Perubahan'}</span>
            </button>
          </div>
        </div>

        {saveSuccessMsg && (
          <div className="p-3.5 rounded-xl bg-emerald-50 border border-emerald-200 text-emerald-800 text-xs font-semibold flex items-center gap-2 animate-in fade-in">
            <CheckCircle2 className="w-4 h-4 shrink-0" />
            <span>{saveSuccessMsg}</span>
          </div>
        )}

        {/* Participants Attendance & Quiz Grid (PRD Section 12, 13, 14, 18) */}
        <div className="bg-white rounded-2xl border border-slate-200 shadow-xs overflow-hidden">
          <div className="p-4 bg-slate-50/80 border-b border-slate-200 flex items-center justify-between">
            <div className="text-xs font-bold text-slate-700 uppercase tracking-wider">
              Daftar Peserta & Kehadiran ({sessionParticipants.length} Peserta)
            </div>
            <div className="text-xs text-slate-500">
              Ubah status kehadiran & input skor nilai secara langsung, lalu klik <strong>"Simpan Perubahan"</strong>.
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead className="bg-slate-100/70 border-b border-slate-200 text-slate-600 font-semibold uppercase">
                <tr>
                  <th className="py-3 px-4 w-12 text-center">No</th>
                  <th className="py-3 px-4">Nama Peserta & Email</th>
                  <th className="py-3 px-4">Cabang</th>
                  <th className="py-3 px-4 text-center w-48">Kehadiran (Attendance)</th>
                  {activeSession.has_quiz === 1 && (
                    <th className="py-3 px-4 text-center w-32">Nilai Quiz (0-100)</th>
                  )}
                  {activeSession.has_quiz === 1 && (
                    <th className="py-3 px-4 text-center w-28">Hasil Kelulusan</th>
                  )}
                  <th className="py-3 px-4 text-center">Subject Status</th>
                  <th className="py-3 px-4 text-right">Aksi</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {loadingParticipants ? (
                  <tr>
                    <td colSpan="8" className="py-16 text-center text-slate-400">
                      <div className="w-6 h-6 border-2 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-2"></div>
                      Memuat daftar peserta batch...
                    </td>
                  </tr>
                ) : sessionParticipants.length === 0 ? (
                  <tr>
                    <td colSpan="8" className="py-16 text-center text-slate-400">
                      Belum ada peserta yang didaftarkan ke batch ini. Klik tombol <strong>"Paste Peserta"</strong> atau <strong>"Tambah 1 Peserta"</strong> di atas.
                    </td>
                  </tr>
                ) : (
                  sessionParticipants.map((p, idx) => {
                    const currentAttendance = pendingAttendance[p.participant_id] || p.attendance;
                    const currentScore = pendingScores[p.participant_id] !== undefined ? pendingScores[p.participant_id] : (p.quiz_score !== null ? p.quiz_score : '');

                    const numScore = parseFloat(currentScore);
                    let computedResult = null;
                    if (!isNaN(numScore) && currentScore !== '') {
                      computedResult = numScore >= passingGrade ? 'PASS' : 'FAIL';
                    }

                    // PRD Subject Completion Rule:
                    // has_quiz = 0 -> Hadir = Complete
                    // has_quiz = 1 -> Hadir + PASS = Complete
                    const isSubjectCompleted = activeSession.has_quiz === 1 
                      ? (currentAttendance === 'Hadir' && computedResult === 'PASS')
                      : (currentAttendance === 'Hadir');

                    return (
                      <tr key={p.participant_id} className="hover:bg-slate-50/80 transition-colors">
                        <td className="py-3 px-4 text-center text-slate-400 font-mono">{idx + 1}</td>
                        <td className="py-3 px-4">
                          <div className="font-bold text-slate-800 text-sm">{p.participant_name}</div>
                          <div className="text-slate-500 text-[11px]">{p.participant_email}</div>
                        </td>
                        <td className="py-3 px-4 text-slate-600">{p.branch || '-'}</td>

                        {/* Attendance Selector */}
                        <td className="py-3 px-4 text-center">
                          <div className="inline-flex rounded-lg border border-slate-300 p-0.5 bg-slate-50">
                            <button
                              type="button"
                              onClick={() => handleAttendanceChange(p.participant_id, 'Hadir')}
                              className={`px-2.5 py-1 rounded-md text-xs font-bold transition-all ${
                                currentAttendance === 'Hadir'
                                  ? 'bg-emerald-600 text-white shadow-xs'
                                  : 'text-slate-600 hover:text-slate-900'
                              }`}
                            >
                              Hadir
                            </button>
                            <button
                              type="button"
                              onClick={() => handleAttendanceChange(p.participant_id, 'Tidak Hadir')}
                              className={`px-2.5 py-1 rounded-md text-xs font-bold transition-all ${
                                currentAttendance === 'Tidak Hadir'
                                  ? 'bg-red-600 text-white shadow-xs'
                                  : 'text-slate-600 hover:text-slate-900'
                              }`}
                            >
                              Tidak Hadir
                            </button>
                            <button
                              type="button"
                              onClick={() => handleAttendanceChange(p.participant_id, 'Belum')}
                              className={`px-2.5 py-1 rounded-md text-xs font-medium transition-all ${
                                currentAttendance === 'Belum'
                                  ? 'bg-slate-300 text-slate-800'
                                  : 'text-slate-400 hover:text-slate-700'
                              }`}
                            >
                              Belum
                            </button>
                          </div>
                        </td>

                        {/* Quiz Score Input */}
                        {activeSession.has_quiz === 1 && (
                          <td className="py-3 px-4 text-center">
                            <input
                              type="number"
                              min="0"
                              max="100"
                              placeholder="0-100"
                              value={currentScore}
                              onChange={(e) => handleScoreChange(p.participant_id, e.target.value)}
                              className="w-20 text-center font-bold text-slate-800 py-1 px-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-purple-500 bg-white"
                            />
                          </td>
                        )}

                        {/* Computed Result Badge */}
                        {activeSession.has_quiz === 1 && (
                          <td className="py-3 px-4 text-center">
                            {computedResult ? (
                              <span className={`px-2.5 py-1 rounded-full font-bold text-[10px] uppercase ${
                                computedResult === 'PASS' 
                                  ? 'bg-emerald-100 text-emerald-800 border border-emerald-300' 
                                  : 'bg-red-100 text-red-800 border border-red-300'
                              }`}>
                                {computedResult}
                              </span>
                            ) : (
                              <span className="text-slate-400 text-xs">-</span>
                            )}
                          </td>
                        )}

                        {/* Subject Completion Indicator */}
                        <td className="py-3 px-4 text-center">
                          {isSubjectCompleted ? (
                            <span className="inline-flex items-center gap-1 text-emerald-700 font-bold bg-emerald-50 border border-emerald-200 px-2 py-0.5 rounded-full text-[10px]">
                              <Check className="w-3 h-3" /> Completed
                            </span>
                          ) : (
                            <span className="text-slate-400 text-[11px]">Incomplete</span>
                          )}
                        </td>

                        <td className="py-3 px-4 text-right">
                          <button
                            onClick={() => handleRemoveParticipant(p.participant_id, p.participant_name)}
                            className="p-1 rounded-lg hover:bg-red-50 text-red-600 transition-colors"
                            title="Hapus Peserta dari Batch"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* Modal: Single Add Participant */}
        {isAddParticipantModalOpen && (
          <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-full max-w-md overflow-hidden animate-in fade-in zoom-in-95 duration-150">
              <div className="px-6 py-4 bg-slate-900 text-white flex items-center justify-between">
                <h3 className="font-bold text-base">Tambah Peserta ke Batch</h3>
                <button onClick={() => setIsAddParticipantModalOpen(false)} className="p-1 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-white">✕</button>
              </div>

              <form onSubmit={handleAddSingleParticipant} className="p-6 space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">Pilih Peserta Aktif</label>
                  <select
                    required
                    value={selectedParticipantToAdd}
                    onChange={(e) => setSelectedParticipantToAdd(e.target.value)}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="">Pilih peserta...</option>
                    {allParticipants
                      .filter(p => !sessionParticipants.some(sp => sp.participant_id === p.id))
                      .map(p => (
                        <option key={p.id} value={p.id}>{p.name} ({p.email})</option>
                      ))}
                  </select>
                </div>

                <div className="pt-3 flex justify-end gap-2 border-t border-slate-100">
                  <button type="button" onClick={() => setIsAddParticipantModalOpen(false)} className="px-4 py-2 rounded-lg border border-slate-300 text-slate-700 text-xs font-semibold hover:bg-slate-50">Batal</button>
                  <button type="submit" disabled={!selectedParticipantToAdd} className="px-5 py-2 rounded-lg bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold disabled:opacity-50">
                    Daftarkan Peserta
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Modal: Batch Paste Add Participants */}
        <CopyPasteModal
          isOpen={isBatchPasteParticipantsOpen}
          onClose={() => {
            setIsBatchPasteParticipantsOpen(false);
            loadSessionParticipants(activeSession.id);
          }}
          type="batch_participants"
          title={`Paste Daftar Peserta ke ${activeSession.batch_name}`}
          subtitle="Tempel daftar email peserta untuk didaftarkan langsung ke batch ini."
          exampleFormat={`budi.santoso@email.com\nsiti.rahma@email.com\nandi.pratama@email.com`}
          placeholder="budi.santoso@email.com\nsiti.rahma@email.com"
          onPreview={(text) => api.previewBatchAddParticipants(activeSession.id, text)}
          onCommit={(items) => api.commitBatchAddParticipants(activeSession.id, items)}
        />

        {/* Modal: Copy Paste Import Quiz Scores (PRD Section 19.2 & 20) */}
        <CopyPasteModal
          isOpen={isImportQuizOpen}
          onClose={() => {
            setIsImportQuizOpen(false);
            loadSessionParticipants(activeSession.id);
          }}
          type="quiz"
          title={`Import Nilai Quiz - ${activeSession.batch_name}`}
          subtitle={`Passing Grade: ${passingGrade}. Peserta otomatis berstatus PASS jika nilai >= ${passingGrade}.`}
          exampleFormat={`budi.santoso@email.com\t85\nsiti.rahma@email.com\t92\nandi.pratama@email.com\t65`}
          placeholder="budi.santoso@email.com\t85\nsiti.rahma@email.com\t92"
          onPreview={(text) => api.previewImportQuiz(activeSession.id, text)}
          onCommit={(items) => api.commitImportQuiz(activeSession.id, items)}
        />

      </div>
    );
  }

  // Render Sessions Table / List View
  return (
    <div className="space-y-6 animate-in fade-in duration-200">

      {/* Header Banner */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-5 rounded-2xl border border-slate-200 shadow-xs">
        <div>
          <h2 className="text-xl font-bold text-slate-800">Pelaksanaan Training / Batch</h2>
          <p className="text-xs text-slate-500 mt-0.5">
            Kelola event training, pencatatan absensi kehadiran, dan penginputan nilai quiz per batch.
          </p>
        </div>

        <button
          onClick={handleOpenCreateSession}
          className="px-4 py-2 rounded-xl bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold flex items-center gap-1.5 transition-all shadow-md shadow-blue-600/20"
        >
          <Plus className="w-4 h-4" />
          <span>Buat Batch Pelaksanaan Baru</span>
        </button>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-3 flex-1">
          <div className="flex items-center gap-2">
            <Filter className="w-3.5 h-3.5 text-slate-400" />
            <select
              value={trainingFilter}
              onChange={(e) => setTrainingFilter(e.target.value)}
              className="text-xs py-1.5 px-2.5 bg-slate-50 border border-slate-200 rounded-lg text-slate-700 max-w-xs"
            >
              <option value="">Semua Master Training</option>
              {trainings.map(t => (
                <option key={t.id} value={t.id}>{t.name}</option>
              ))}
            </select>

            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="text-xs py-1.5 px-2.5 bg-slate-50 border border-slate-200 rounded-lg text-slate-700"
            >
              <option value="">Semua Status</option>
              <option value="Scheduled">Scheduled</option>
              <option value="Ongoing">Ongoing</option>
              <option value="Completed">Completed</option>
              <option value="Cancelled">Cancelled</option>
            </select>
          </div>
        </div>

        <div className="text-xs text-slate-500 font-medium">
          Ditemukan <strong>{sessions.length}</strong> pelaksanaan batch
        </div>
      </div>

      {/* Sessions Table */}
      <div className="bg-white rounded-2xl border border-slate-200 shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="bg-slate-50 border-b border-slate-200 text-slate-600 font-semibold uppercase">
              <tr>
                <th className="py-3 px-4">Tanggal & Batch</th>
                <th className="py-3 px-4">Materi Training Master</th>
                <th className="py-3 px-4">Trainer & Lokasi</th>
                <th className="py-3 px-4 text-center">Peserta / Hadir</th>
                <th className="py-3 px-4 text-center">Quiz Lulus</th>
                <th className="py-3 px-4 text-center">Status</th>
                <th className="py-3 px-4 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan="7" className="py-16 text-center text-slate-400">
                    <div className="w-6 h-6 border-2 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-2"></div>
                    Memuat data pelaksanaan batch...
                  </td>
                </tr>
              ) : sessions.length === 0 ? (
                <tr>
                  <td colSpan="7" className="py-16 text-center text-slate-400">
                    Belum ada data pelaksanaan training.
                  </td>
                </tr>
              ) : (
                sessions.map(s => (
                  <tr 
                    key={s.id} 
                    onClick={() => handleOpenSessionDetail(s)}
                    className="hover:bg-blue-50/40 cursor-pointer transition-colors"
                  >
                    <td className="py-3 px-4">
                      <div className="text-xs font-mono font-bold text-slate-500">{s.date}</div>
                      <div className="font-bold text-slate-800 text-sm mt-0.5">{s.batch_name}</div>
                    </td>
                    <td className="py-3 px-4">
                      <div className="font-bold text-slate-800">{s.training_name}</div>
                      <span className="inline-block mt-0.5 text-[10px] font-bold px-1.5 py-0.2 rounded bg-blue-50 text-blue-700 border border-blue-100">
                        {s.level_name} • {s.subject_name}
                      </span>
                    </td>
                    <td className="py-3 px-4">
                      <div className="text-slate-700 font-medium">{s.trainer || '-'}</div>
                      <div className="text-slate-400 text-[11px] flex items-center gap-1">
                        {s.location && <><MapPin className="w-3 h-3" /> {s.location}</>}
                      </div>
                    </td>
                    <td className="py-3 px-4 text-center">
                      <span className="font-bold text-slate-800 text-sm">{s.attended_count || 0}</span>
                      <span className="text-slate-400"> / {s.total_participants || 0} Hadir</span>
                    </td>
                    <td className="py-3 px-4 text-center">
                      {s.has_quiz ? (
                        <span className="font-bold text-emerald-600 text-sm">
                          {s.passed_count || 0} <span className="text-slate-400 text-xs font-normal">/ {s.quiz_submitted_count || 0}</span>
                        </span>
                      ) : (
                        <span className="text-slate-400">-</span>
                      )}
                    </td>
                    <td className="py-3 px-4 text-center">
                      <span className={`px-2.5 py-0.5 rounded-full font-bold uppercase text-[10px] ${
                        s.status === 'Completed' ? 'bg-emerald-100 text-emerald-800 border border-emerald-200' :
                        s.status === 'Ongoing' ? 'bg-amber-100 text-amber-800 border border-amber-200' :
                        s.status === 'Cancelled' ? 'bg-red-100 text-red-800 border border-red-200' :
                        'bg-slate-100 text-slate-600 border border-slate-300'
                      }`}>
                        {s.status}
                      </span>
                    </td>
                    <td className="py-3 px-4 text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleOpenSessionDetail(s);
                          }}
                          className="px-2.5 py-1.5 rounded-lg bg-blue-50 hover:bg-blue-100 text-blue-700 font-bold text-xs flex items-center gap-1"
                        >
                          <UserCheck className="w-3.5 h-3.5" />
                          <span>Absensi & Nilai</span>
                        </button>
                        <button
                          onClick={(e) => handleOpenEditSession(s, e)}
                          className="p-1.5 rounded-lg hover:bg-slate-100 text-slate-600"
                          title="Edit Batch"
                        >
                          <Edit className="w-3.5 h-3.5" />
                        </button>
                        <button
                          onClick={(e) => handleDeleteSession(s, e)}
                          className="p-1.5 rounded-lg hover:bg-red-50 text-red-600"
                          title="Hapus Batch"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add / Edit Session Modal */}
      {isSessionModalOpen && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-full max-w-md overflow-hidden animate-in fade-in zoom-in-95 duration-150">
            <div className="px-6 py-4 bg-slate-900 text-white flex items-center justify-between">
              <h3 className="font-bold text-base">
                {editingSession ? 'Edit Pelaksanaan Batch' : 'Buat Pelaksanaan Batch Baru'}
              </h3>
              <button onClick={() => setIsSessionModalOpen(false)} className="p-1 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-white">✕</button>
            </div>

            <form onSubmit={handleSubmitSession} className="p-6 space-y-4">
              {modalError && (
                <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-xs text-red-700 flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 shrink-0" />
                  <span>{modalError}</span>
                </div>
              )}

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Master Training <span className="text-red-500">*</span>
                </label>
                <select
                  required
                  value={sessionForm.training_id}
                  onChange={(e) => setSessionForm({ ...sessionForm, training_id: e.target.value })}
                  className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                >
                  <option value="">Pilih Master Training...</option>
                  {trainings.map(t => (
                    <option key={t.id} value={t.id}>[{t.level_name}] {t.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                  Nama Batch / Event <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  required
                  placeholder="Contoh: Batch 01 Jakarta"
                  value={sessionForm.batch_name}
                  onChange={(e) => setSessionForm({ ...sessionForm, batch_name: e.target.value })}
                  className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">
                    Tanggal Pelaksanaan <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="date"
                    required
                    value={sessionForm.date}
                    onChange={(e) => setSessionForm({ ...sessionForm, date: e.target.value })}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">Status</label>
                  <select
                    value={sessionForm.status}
                    onChange={(e) => setSessionForm({ ...sessionForm, status: e.target.value })}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="Scheduled">Scheduled</option>
                    <option value="Ongoing">Ongoing</option>
                    <option value="Completed">Completed</option>
                    <option value="Cancelled">Cancelled</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">Trainer</label>
                  <input
                    type="text"
                    placeholder="Nama Trainer"
                    value={sessionForm.trainer}
                    onChange={(e) => setSessionForm({ ...sessionForm, trainer: e.target.value })}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase mb-1">Lokasi</label>
                  <input
                    type="text"
                    placeholder="Ruang / Zoom"
                    value={sessionForm.location}
                    onChange={(e) => setSessionForm({ ...sessionForm, location: e.target.value })}
                    className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase mb-1">Catatan</label>
                <textarea
                  rows={2}
                  placeholder="Catatan pelaksanaan..."
                  value={sessionForm.notes}
                  onChange={(e) => setSessionForm({ ...sessionForm, notes: e.target.value })}
                  className="w-full text-xs p-2.5 rounded-lg border border-slate-300 focus:outline-hidden focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div className="pt-3 flex justify-end gap-2 border-t border-slate-100">
                <button
                  type="button"
                  onClick={() => setIsSessionModalOpen(false)}
                  className="px-4 py-2 rounded-lg border border-slate-300 text-slate-700 text-xs font-semibold hover:bg-slate-50"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className="px-5 py-2 rounded-lg bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold disabled:opacity-50"
                >
                  {isSubmitting ? 'Menyimpan...' : 'Simpan Batch'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </div>
  );
}

