import React, { useState, useEffect } from 'react';
import { 
  Settings, 
  Database, 
  HardDriveDownload, 
  RotateCcw, 
  Download, 
  Shield, 
  Key, 
  CheckCircle2, 
  AlertCircle, 
  Lock,
  FileSpreadsheet,
  AlertTriangle
} from 'lucide-react';
import { api } from '../services/api';

export default function SettingsPage() {
  const [backups, setBackups] = useState([]);
  const [loadingBackups, setLoadingBackups] = useState(true);
  const [backupMsg, setBackupMsg] = useState('');
  const [errorMsg, setErrorMsg] = useState('');

  // Password state
  const [pwdForm, setPwdForm] = useState({ current_password: '', new_password: '', confirm_password: '' });
  const [pwdMsg, setPwdMsg] = useState('');
  const [pwdError, setPwdError] = useState('');
  const [isChangingPwd, setIsChangingPwd] = useState(false);

  // Restore confirmation modal
  const [restoreCandidate, setRestoreCandidate] = useState(null);
  const [isRestoring, setIsRestoring] = useState(false);

  useEffect(() => {
    loadBackups();
  }, []);

  const loadBackups = async () => {
    setLoadingBackups(true);
    try {
      const list = await api.getBackups();
      setBackups(list);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingBackups(false);
    }
  };

  const handleCreateBackup = async () => {
    setBackupMsg('');
    setErrorMsg('');
    try {
      const res = await api.createBackup();
      setBackupMsg(`Backup baru berhasil dibuat: ${res.backup.filename}`);
      loadBackups();
    } catch (err) {
      setErrorMsg(err.message || 'Gagal membuat backup.');
    }
  };

  const handleConfirmRestore = async () => {
    if (!restoreCandidate) return;
    setIsRestoring(true);
    setErrorMsg('');
    setBackupMsg('');

    try {
      const res = await api.restoreBackup(restoreCandidate.filename);
      setBackupMsg(res.message || 'Database berhasil direstore.');
      setRestoreCandidate(null);
      loadBackups();
    } catch (err) {
      setErrorMsg(err.message || 'Gagal merestore database.');
    } finally {
      setIsRestoring(false);
    }
  };

  const handleChangePassword = async (e) => {
    e.preventDefault();
    if (!pwdForm.current_password || !pwdForm.new_password) {
      setPwdError('Semua kolom password wajib diisi.');
      return;
    }
    if (pwdForm.new_password !== pwdForm.confirm_password) {
      setPwdError('Konfirmasi password baru tidak cocok.');
      return;
    }

    setIsChangingPwd(true);
    setPwdMsg('');
    setPwdError('');

    try {
      await api.changePassword(pwdForm.current_password, pwdForm.new_password);
      setPwdMsg('Password admin berhasil diubah.');
      setPwdForm({ current_password: '', new_password: '', confirm_password: '' });
    } catch (err) {
      setPwdError(err.message || 'Gagal mengubah password.');
    } finally {
      setIsChangingPwd(false);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-200">

      {/* Header Banner */}
      <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-xs">
        <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <Settings className="w-5 h-5 text-blue-600" />
          <span>Pengaturan Sistem, Backup & Export</span>
        </h2>
        <p className="text-xs text-slate-500 mt-0.5">
          Manajemen pencadangan database SQLite lokal, pemulihan data (restore), export laporan CSV, dan keamanan akun admin.
        </p>
      </div>

      {backupMsg && (
        <div className="p-3.5 rounded-xl bg-emerald-50 border border-emerald-200 text-emerald-800 text-xs font-semibold flex items-center gap-2 animate-in fade-in">
          <CheckCircle2 className="w-4 h-4 shrink-0" />
          <span>{backupMsg}</span>
        </div>
      )}

      {errorMsg && (
        <div className="p-3.5 rounded-xl bg-red-50 border border-red-200 text-red-800 text-xs font-semibold flex items-center gap-2 animate-in fade-in">
          <AlertCircle className="w-4 h-4 shrink-0" />
          <span>{errorMsg}</span>
        </div>
      )}

      {/* Grid: Backup / Restore & Export Data */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Backup & Restore (PRD Section 27) */}
        <div className="lg:col-span-2 space-y-6">

          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-xs">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
