              >
                <HardDriveDownload className="w-4 h-4" />
                <span>Buat Backup Sekarang</span>
              </button>
            </div>

            {/* Backups List Table */}
            <div className="border border-slate-200 rounded-xl overflow-hidden">
              <table className="w-full text-left text-xs">
                <thead className="bg-slate-50 border-b border-slate-200 text-slate-600 font-semibold uppercase">
                  <tr>
                    <th className="py-2.5 px-3">Nama File Backup</th>
                    <th className="py-2.5 px-3">Ukuran File</th>
                    <th className="py-2.5 px-3">Waktu Pembuatan</th>
                    <th className="py-2.5 px-3 text-right">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {loadingBackups ? (
                    <tr>
                      <td colSpan="4" className="py-8 text-center text-slate-400">
                        Memuat daftar backup...
                      </td>
                    </tr>
                  ) : backups.length === 0 ? (
                    <tr>
                      <td colSpan="4" className="py-8 text-center text-slate-400">
                        Belum ada file backup database. Klik tombol "Buat Backup Sekarang".
                      </td>
                    </tr>
                  ) : (
                    backups.map((b, i) => (
                      <tr key={i} className="hover:bg-slate-50/80 transition-colors">
