          <p className="text-sm font-medium text-slate-400">Memuat Aplikasi Training Agency...</p>
        </div>
      </div>
    );
  }

  // If public mode requested without login, show public dashboard
  if (isPublicMode && !admin) {
    return <PublicDashboardPage onBackToAdmin={() => setIsPublicMode(false)} />;
  }

  // If not logged in, show login page
  if (!admin) {
    return <LoginPage onOpenPublicMode={() => setIsPublicMode(true)} />;
  }

  // If logged in and public view is toggled
  if (isPublicMode) {
    return <PublicDashboardPage onBackToAdmin={() => setIsPublicMode(false)} />;
  }

  const getPageTitle = () => {
    switch (activeTab) {
      case 'dashboard': return { title: 'Dashboard Utama', subtitle: 'Ringkasan performa pelatihan, status kelulusan kurikulum & leaderboard' };
      case 'participants': return { title: 'Daftar Peserta / Agen', subtitle: 'Manajemen data agen, riwayat kehadiran, dan monitoring kelulusan level' };
      case 'curriculum': return { title: 'Kurikulum & Subject', subtitle: 'Struktur level berjenjang (Basic, Intermediate, Advance) dan materi wajib' };
      case 'trainings': return { title: 'Master Training', subtitle: 'Katalog materi training, pengaturan quiz, dan passing grade kelulusan' };
      case 'sessions': return { title: 'Pelaksanaan Training / Batch', subtitle: 'Pencatatan batch, absensi kehadiran, dan input nilai quiz peserta' };
      case 'ranking': return { title: 'Ranking & Leaderboard', subtitle: 'Peringkat rata-rata nilai quiz seluruh peserta dengan filter interaktif' };
      case 'settings': return { title: 'Backup & Pengaturan Sistem', subtitle: 'Pencadangan database SQLite lokal, pemulihan data, dan export laporan CSV' };
      default: return { title: 'Training Agency', subtitle: 'Local Desktop MVP' };
    }
  };

  const { title, subtitle } = getPageTitle();

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden font-sans">

      {/* Toast Notification */}
      {toastMessage && (
        <div className="fixed bottom-6 right-6 z-50 bg-slate-900 text-white px-4 py-3 rounded-xl shadow-2xl border border-slate-700 flex items-center gap-2 text-xs font-semibold animate-in slide-in-from-bottom-5">
          <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
          <span>{toastMessage}</span>
        </div>
      )}

      {/* Sidebar */}
      <Sidebar
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        onLogout={logout}
        isPublicMode={isPublicMode}
        setIsPublicMode={setIsPublicMode}
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">

        {/* Top Header */}
        <Header
          title={title}
          subtitle={subtitle}
          admin={admin}
          isPublicMode={isPublicMode}
          setIsPublicMode={setIsPublicMode}
          onQuickBackup={handleQuickBackup}
        />

        {/* Scrollable Page Body */}
        <main className="flex-1 overflow-y-auto p-6 bg-slate-100/70">
          {activeTab === 'dashboard' && <DashboardPage setActiveTab={setActiveTab} />}
          {activeTab === 'participants' && <ParticipantsPage />}
          {activeTab === 'curriculum' && <CurriculumPage />}
          {activeTab === 'trainings' && <TrainingsPage />}
          {activeTab === 'sessions' && <SessionsPage />}
          {activeTab === 'ranking' && <RankingPage />}
          {activeTab === 'settings' && <SettingsPage />}
        </main>

      </div>
    </div>
  );
}

