  previewImportQuizScores,
  executeImportQuizScores
} = require('../server/services/importService');
const { createBackup, listBackups } = require('../server/services/backupService');

console.log('--- STARTING AUTOMATED PRD VERIFICATION TESTS ---');

initDb();
const db = getDb();

// Test 1: Budi Santoso (Seed has attended 2 subjects in Basic and passed quiz)
const budi = db.prepare("SELECT id FROM participants WHERE email = 'budi.santoso@email.com'").get();
assert(budi, 'Budi Santoso should exist');

const budiProgress = getParticipantLevelProgress(budi.id);
console.log('✓ Test 1: Budi Level Progress:', budiProgress.map(p => `${p.level_name}: ${p.completed_required}/${p.total_required} (${p.percentage}%) - ${p.status}`));
const basicProgress = budiProgress.find(p => p.level_name === 'Basic');
assert.strictEqual(basicProgress.status, 'In Progress');
assert.strictEqual(basicProgress.completed_required, 2);

// Test 2: Quiz Failure behavior (Andi failed quiz score 65 < 75 passing grade)
const andi = db.prepare("SELECT id FROM participants WHERE email = 'andi.pratama@email.com'").get();
const andiSubjects = getParticipantSubjectsStatus(andi.id);
const basicFoundationSub = andiSubjects.find(s => s.subject_name === 'Basic Insurance Knowledge');
assert.strictEqual(basicFoundationSub.is_completed, false, 'Failed quiz must not mark subject completed');
console.log('✓ Test 2: Quiz Failure correctly leaves subject as Incomplete (Attendance=Hadir, Result=FAIL)');

// Test 3: Training with NO QUIZ completion (Attendance=Hadir -> Completed)
const subSelling = db.prepare("SELECT id FROM subjects WHERE name = 'Basic Selling Skill'").get();
const trnSelling = db.prepare("SELECT id FROM trainings WHERE subject_id = ?").get(subSelling.id);

const sessSelling = db.prepare(`
  INSERT INTO training_sessions (training_id, batch_name, date, status)
  VALUES (?, 'Batch Test No Quiz', '2026-09-05', 'Completed')
`).run(trnSelling.id);

db.prepare(`
  INSERT INTO session_participants (session_id, participant_id, attendance, status)
  VALUES (?, ?, 'Hadir', 'Completed')
`).run(sessSelling.lastInsertRowid, andi.id);

const andiSubjectsAfter = getParticipantSubjectsStatus(andi.id);
const sellingSubAfter = andiSubjectsAfter.find(s => s.subject_name === 'Basic Selling Skill');
assert.strictEqual(sellingSubAfter.is_completed, true, 'Training with no quiz and attendance Hadir must mark subject completed');
console.log('✓ Test 3: Training with NO Quiz completes subject upon Hadir');

