/**
 * Create a timestamped backup of the SQLite database
 */
async function createBackup() {
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-').replace('T', '_').slice(0, 19);
  const backupFileName = `backup_training_agency_${timestamp}.db`;
  const destinationPath = path.join(backupsDir, backupFileName);

  const db = getDb();
  // Use better-sqlite3 backup API for safe hot backup
  await db.backup(destinationPath);

  const stats = fs.statSync(destinationPath);

  return {
    filename: backupFileName,
    path: destinationPath,
    size_bytes: stats.size,
    size_formatted: `${(stats.size / 1024).toFixed(1)} KB`,
    created_at: new Date().toISOString()
  };
}

