 */
async function restoreBackup(backupFilename) {
  const sourcePath = path.isAbsolute(backupFilename)
    ? backupFilename
    : path.join(backupsDir, backupFilename);

  if (!fs.existsSync(sourcePath)) {
    throw new Error('File backup tidak ditemukan.');
  }

  // Create an automatic safety backup before restoring
  await createBackup();

  // Reset database connection and copy file
  resetDbConnection();
  fs.copyFileSync(sourcePath, dbPath);
  resetDbConnection();

  return {
    success: true,
    message: `Database berhasil direstore dari file ${path.basename(sourcePath)}`
  };
}

