  assert.strictEqual(sellingSubAfter.is_completed, true, 'Training with no quiz and attendance Hadir must mark subject completed');
  console.log('✓ Test 3: Training with NO Quiz completes subject upon Hadir');

  // Test 4: Copy-Paste Import Peserta Validator
  const rawPastePeserta = `
test.user1@agency.com\tTest User 1\t3171000000000001\t08111111111\tJakarta
test.user2@agency.com\tTest User 2\t3171000000000002\t08222222222\tSurabaya
invalid-email-row\tNo Email\t\t\t
budi.santoso@email.com\tDuplicate Budi\t\t\t
  `;
  const previewPeserta = previewImportParticipants(rawPastePeserta);
  console.log(`✓ Test 4: Import Peserta Validation -> Valid: ${previewPeserta.valid_count}, Invalid: ${previewPeserta.invalid_count}`);
  assert.strictEqual(previewPeserta.valid_count, 2);
  assert.strictEqual(previewPeserta.invalid_count, 2);

  // Test 5: Copy-Paste Import Quiz Scores Validator
  const rawPasteQuiz = `
andi.pratama@email.com\t95
budi.santoso@email.com\t80
nonexistent@email.com\t88
  `;
  const previewQuiz = previewImportQuizScores(sessSelling.lastInsertRowid, rawPasteQuiz);
  console.log(`✓ Test 5: Import Quiz Validation -> Valid: ${previewQuiz.valid_count}, Invalid: ${previewQuiz.invalid_count}`);
  assert.strictEqual(previewQuiz.valid_count, 1);
  assert.strictEqual(previewQuiz.invalid_count, 2);

  // Test 6: Database Backup
  const backup = await createBackup();
  console.log(`✓ Test 6: Database backup created successfully -> ${backup.filename} (${backup.size_formatted})`);
  const backupsList = listBackups();
  assert(backupsList.length > 0);

  console.log('=============================================');
  console.log('ALL PRD ACCEPTANCE CRITERIA AUTOMATED TESTS PASSED SUCCESSFULLY!');
  console.log('=============================================');
}

runTests().catch(err => {
  console.error('Test error:', err);
  process.exit(1);
});

